window.__T__=[{"i":10000,"text":"{\"type\":\"电影级赛博朋克动漫动作项目联系表\",\"format\":\"3x3 九宫格，带有细黑色边框\",\"subject\":{\"character\":\"{argument name=\\\"character name\\\" default=\\\"赛博狐狸面具武士\\\"}\",\"mask\":\"发光的蓝白色狐狸面具，带有尖耳朵、霓虹线条标记、空白发光的眼睛\",\"hair\":\"{argument name=\\\"hair color\\\" default=\\\"长而飘逸的银蓝色头发\\\"}\",\"outfit\":\"层叠的深色和服式赛博忍者长袍、黑色装甲纹理、湿润有光泽的布料、腰带和战术绑带\",\"weapon\":\"{argument name=\\\"weapon\\\" default=\\\"双头电动薙刀，带有发光的蓝紫色刀刃\\\"}\",\"aura\":\"紫青色闪电、幽灵般的火焰、能量轨迹、超自然的狐灵气息\"},\"setting\":{\"environment\":\"{argument name=\\\"setting\\\" default=\\\"雨夜中霓虹闪烁的赛博朋克城市\\\"}\",\"background\":\"高耸的深色摩天大楼、全息蓝紫色灯光、反光的湿润地面、垂直光束、漂浮的幽灵火焰\",\"lighting\":\"高对比度电光蓝和紫外线轮廓光、体积雾、火花、发光粒子、电影级光晕\"},\"layout\":{\"panel count\":9,\"grid\":\"三列三行\",\"visible labels\":[\"T-5\",\"T-5 ALT\",\"T-1\",\"T\",\"T+1\",\"T+5\",\"T+5 ALT\",\"T+30\",\"FINAL FRAME\"],\"panels\":[{\"label\":\"T-5\",\"position\":\"左上\",\"description\":\"远景全身镜头，武士悬浮或下降在蓝白色的垂直光柱中，双臂伸展，双发光刀刃向下，周围是城市剪影\"},{\"label\":\"T-5 ALT\",\"position\":\"中上\",\"description\":\"动态后侧方动作视角，长袍和长发随风飘动，长矛斜跨身体，紫色灵魂火焰在黑暗城市中漂浮\"},{\"label\":\"T-1\",\"position\":\"右上\",\"description\":\"近景上半身镜头，狐狸面具发光，长发散开，双手水平握住电动长矛，闪电在武器上蔓延\"},{\"label\":\"T\",\"position\":\"左中\",\"description\":\"英雄般的跪姿或蹲姿战斗姿态，长矛从左下斜向右上，强烈的蓝色刀刃光芒，角色周围环绕着多个紫蓝色幽灵火焰\"},{\"label\":\"T+1\",\"position\":\"正中\",\"description\":\"空中旋转跳跃，身体背向镜头，圆形霓虹运动轨迹环绕着武士和武器\"},{\"label\":\"T+5\",\"position\":\"右中\",\"description\":\"侧后方动作特写，武士向前冲刺，头发戏剧性地飘动，长矛刀刃在右下方发光，能量弧在雨中划过\"},{\"label\":\"T+5 ALT\",\"position\":\"左下\",\"description\":\"面具和握矛双手的紧凑特写，强烈的发光狐狸面具，紫色电流缠绕在武器杆和刀刃上\"},{\"label\":\"T+30\",\"position\":\"中下\",\"description\":\"在反光湿润路面上的全身站立余波姿态，长矛垂在一侧，长发飘逸，背景是远处的霓虹塔\"},{\"label\":\"FINAL FRAME\",\"position\":\"右下\",\"description\":\"戏剧性的最终特写，武士将发光的长矛刀刃刺向观众，狐狸面具居中，紫色火焰在身后漂浮\"}]},\"style\":{\"rendering\":\"超精细数字插画、动漫写实奇幻、暗黑赛博朋克、用于动画定时的电影级关键帧、清晰对焦、高细节布料和装甲、仅在动作面板中有强烈的运动模糊\",\"palette\":\"深黑色、电光钴蓝色、青色、紫色、洋红色火焰点缀\",\"mood\":\"神秘、超自然、快速、强大、优雅\"},\"text\":{\"panel labels\":\"每个面板左上角的小型黑色矩形标签，带有白色时间文本\",\"include headline\":false},\"quality\":\"高分辨率、精致的概念艺术、九个画面中统一的角色设计、无额外角色、无水印\"}","imgs":["https://r2.qqsrc.com/images/originals/17943.jpg"]},{"i":10001,"text":"{\"type\":\"优雅的日式手相指南信息图\",\"language\":\"日文可见文本\",\"style\":\"极简高级编辑设计，暖米色纸张背景，细黑与米色线条艺术，柔和圆角卡片，精致金色点缀，宁静的占卜美学，高分辨率，留白整洁\",\"main_title\":\"{argument name=\\\"headline text\\\" default=\\\"手相鉴定指南\\\"}\",\"subtitle\":\"{argument name=\\\"subtitle text\\\" default=\\\"从你的掌纹解读性格与运势\\\"}\",\"layout\":{\"orientation\":\"portrait\",\"top\":\"大型居中日文标题，上方带有小金星点缀，下方为副标题，配有细金色水平分割线\",\"centerpiece\":\"一张张开手掌的大型简约线条画，面向观众，黑色轮廓配有淡淡的掌纹，置于右侧中心，带有引导线和点状标记指向掌纹\",\"summary_card\":{\"position\":\"左上角\",\"title\":\"{argument name=\\\"type label\\\" default=\\\"综合类型\\\"}\",\"icon\":\"圆圈内的小指南针星\",\"body\":\"平衡的现实主义类型。\\n思虑周全且诚实，重视\\n周围人的信任。\\n通过不断的努力，\\n能够稳步实现理想。\"},\"palm_labels\":{\"count\":6,\"labels\":[{\"text\":\"感情线\",\"position\":\"手掌左上方，引导线指向手掌上部\"},{\"text\":\"知能线\",\"position\":\"左侧中部，水平引导线指向手掌中心\"},{\"text\":\"生命线\",\"position\":\"左侧下部，水平引导线指向大拇指弧度\"},{\"text\":\"太阳线\",\"position\":\"右侧上部，引导线指向无名指区域\"},{\"text\":\"财运线\",\"position\":\"右侧中部，引导线指向小指侧\"},{\"text\":\"命运线\",\"position\":\"右侧下部，引导线指向垂直中心线\"}]},\"analysis_cards\":{\"position\":\"底部两行，每行三张圆角卡片\",\"count\":6,\"cards\":[{\"number\":\"1\",\"icon\":\"leaf\",\"title\":\"生命线\",\"body\":\"长度适中且弧度平滑的\\n生命线。\\n体力和恢复力稳定，\\n只要不过度劳累，\\n就能保持长期稳定的运势。\"},{\"number\":\"2\",\"icon\":\"light bulb\",\"title\":\"知能线\",\"body\":\"略长且微微向下延伸的\\n知能线。\\n逻辑思维能力强，同时\\n想象力和直觉也很丰富。\\n能以灵活的思维开辟道路。\"},{\"number\":\"3\",\"icon\":\"heart\",\"title\":\"感情线\",\"body\":\"平和且平衡感良好的感情线。\\n诚实且富有同情心，擅长\\n情绪管理。\\n是能够建立值得信赖的\\n稳定关系的人。\"},{\"number\":\"4\",\"icon\":\"flag\",\"title\":\"命运线\",\"body\":\"清晰可见但不过分浓重的\\n命运线。\\n属于靠自己开辟道路的类型，\\n努力容易获得回报。\\n随着经验积累，运势会愈发强劲。\"},{\"number\":\"5\",\"icon\":\"sun\",\"title\":\"太阳线・财运线\",\"body\":\"太阳线和财运线细长且有多条，\\n人气运和财运会随着信任的积累\\n以及 技能 的提升\\n而缓慢上升。\\n持续努力是关键。\"},{\"number\":\"6\",\"icon\":\"feather pen\",\"title\":\"建议\",\"body\":\"发挥分析力和直觉的平衡，\\n以长期视角磨练专业能力。\\n当思虑过多而无法行动时，\\n请重视迈出小小的一步。\\n持续积累将通向未来的巨大成功。\"}]},\"footer\":{\"position\":\"底部全宽圆角矩形\",\"decorations\":\"左右两侧带有金色星形图标\",\"text\":\"{argument name=\\\"footer message\\\" default=\\\"你的手是“稳步积累、闪耀光芒的手相”。\\n重视信任、努力与持续，\\n你能够亲手创造理想的未来。\\\"}\"}},\"typography\":\"标题采用日式明朝体，正文使用清晰易读的日文字体，黑色墨迹配以柔和的米色数字圆圈\",\"composition_notes\":\"使用精确的 6 张卡片计数，精确的 6 个掌纹标签，克制的单色线条，无摄影图片，无手持物品，无杂乱元素。\"}","imgs":["https://r2.qqsrc.com/images/originals/17944.jpg"]},{"i":10002,"text":"创作一幅温馨的手绘彩色铅笔和蜡笔风格插画，描绘一个可爱的柔和色调学习室角落，具有温暖的米色纸张质感和素描感的棕色轮廓。画面中展示一位年轻女性，留着 {argument name=\"hair color\" default=\"长波浪浅棕色头发\"}，坐在木桌前用黑色钢笔在打开的日记本上书写；她的脸部被一个简单的米色方形遮挡块刻意遮住。她穿着带有蕾丝花边和蝴蝶结的粉色格子荷叶边连衣裙，坐在木椅上，脚下铺着粉色扇形地毯。房间内包含 1 张带 2 个可见抽屉的大木桌、1 本打开的笔记本、1 叠闭合的粉色书籍、1 个带托盘的茶杯、1 支钢笔、1 把木椅、1 个窗外有花的窗帘窗户、1 条悬挂的藤蔓、4 盆盆栽、1 个放着彩色书籍的书架、1 个小相框、1 个花卉台灯以及墙上 1 幅装裱的花卉画。包含 2 个可见的文字标签：一个写着 {argument name=\"wall sign text\" default=\"luffynodoo\"} 的粉色悬挂墙牌，以及一个写着 {argument name=\"cloud text\" default=\"ももいろ\\nメモリーズ♡\"} 的云朵对话气泡牌。场景周围环绕着可爱的涂鸦：4 朵大粉花、8 颗黄星星、1 朵蓝色笑脸云、1 根粉色棒棒糖、1 颗包装糖果，以及小爱心和闪光点。采用柔和的粉色、奶油色、蜜棕色、淡黄色、薄荷绿和婴儿蓝，呈现出奇幻的日式文具美学、精致的交叉排线、温暖的阳光，且不追求写实感。","imgs":["https://r2.qqsrc.com/images/originals/17945.jpg"]},{"i":10003,"text":"创建一个细节极其丰富的温馨微缩立体模型房间，采用柔和的粉彩色调、手绘故事书动漫风格，以四分之三等轴测视角呈现，如同一个带有米色缝合织物墙壁和地板边缘的微型开口盒子。场景中心是一位坐在木制书桌前的年轻女性，她穿着粉色格子裙，带有荷叶边露肩袖、蕾丝饰边、胸前蝴蝶结和精致的项链；她长长的 {argument name=\"hair color\" default=\"波浪状浅棕色\"} 头发垂在肩上，脸部被一个平坦的棕褐色方形遮挡块覆盖。她正拿着笔在桌上的打开的笔记本上书写。书桌上包含 10 个清晰可见的桌面物品：一本打开的笔记本、她手中的一支笔、一个装有茶的茶托茶杯、一本闭合的粉色笔记本、两颗圆形纽扣、一颗蓝色包装的糖果、一颗粉色条纹糖果、一颗微小的黄色糖果和一朵小花。左侧添加一扇带有蕾丝窗帘的温暖木窗，花园的光线从中透入；窗外是粉色的玫瑰和绿植。在窗户附近添加三朵蓬松的白云，房间周围点缀着小星星和花朵涂鸦。在右侧墙上放置一个粉色缝合的名牌，上面写着 {argument name=\"wall sign text\" default=\"luffynodoo\"}，周围环绕着微小的心形涂鸦，以及两个蓝色云朵涂鸦和两个黄色星星涂鸦。右侧摆放一个小木架和柜子，里面放着四本直立的书、一盆多肉植物、一个灯罩和一个贴有 {argument name=\"jar label\" default=\"CANDY\"} 标签的罐子。地板上放置一个编织植物篮、一把木椅、一块红色小地毯，并散布着刺绣般的小花、环绕的黄色丝线，以及随处可见的精致糖果、花朵、星星和云朵图案。使用温暖的阳光、柔和的阴影、逼真的微缩质感、刺绣织物接缝、精致的蕾丝、木纹、柔和的粉色和米色调，营造可爱奇幻的氛围，高细节，方形构图，除墙面标志和糖果罐标签外，不包含任何额外文字。","imgs":["https://r2.qqsrc.com/images/originals/17947.jpg"]},{"i":10004,"text":"{\"type\":\"高度精细的等距视角隐藏物品旅行插画\",\"concept\":\"一个温馨的京都纪念品街场景，观众需要在其中寻找名为 {argument name=\\\"mascot name\\\" default=\\\"ルヒア\\\"} 的小吉祥物，呈现出一种奇思妙想的“寻找角色”解谜感。\",\"setting\":{\"location\":\"寺庙附近的京都古老参道\",\"season\":\"{argument name=\\\"season\\\" default=\\\"春季樱花季\\\"}\",\"time\":\"温暖的金色傍晚，伴有发光的商店灯笼\",\"architecture\":\"传统的木质町屋商店、深色弧形瓦屋顶、格子窗、狭窄的石板巷，远处是景深虚化处理的多层宝塔和寺庙建筑\",\"atmosphere\":\"热闹的黄金周旅游氛围，拥挤而可爱，怀旧，微缩模型感\"},\"style\":{\"visual_style\":\"超精细可爱 3D 微缩模型，Q 版人偶人群，移轴摄影效果，温暖的电影感光效，密集的隐藏物品构图，玩具般的质感，浅景深\",\"camera\":\"高处四分之三等距视角，俯瞰狭窄的商业街，竖屏构图\",\"color_palette\":\"暖棕色、灯笼红、柔和的樱花粉、奶油色纸质招牌、色彩丰富的纪念品包装\"},\"main_scene\":{\"crowd\":\"数十名身着花纹和服与浴衣的 Q 版儿童和游客挤满街道；大头、亮晶晶的眼睛，小手拿着甜点、雨伞、护身符、烤串和纪念品\",\"shops\":\"左右两侧各有两家主要的纪念品店，摆满了招财猫、达摩玩偶、盒装甜点、扇子、护身符、糖果、抹茶点心和小玩具\",\"hidden_object\":\"将吉祥物 {argument name=\\\"mascot name\\\" default=\\\"ルヒア\\\"} 自然地隐藏在纪念品或人群中，它是一个有着可爱脸庞的圆滚滚黄色小鸟状角色，不显眼但可以找到。\",\"top_right_banner\":\"带有棕色边框的装饰性奶油色招牌，上面写着 {argument name=\\\"headline text\\\" default=\\\"ルヒア?を探せ!\\\"}，文字旁边还有该圆滚滚吉祥物的小插图。\"},\"visible_text_and_signs\":{\"count\":9,\"labels\":[{\"text\":\"ルヒア?を探せ!\",\"position\":\"右上角装饰性横幅\"},{\"text\":\"八ツ橋\",\"position\":\"左侧前景的大红灯笼\"},{\"text\":\"京都名物 八ツ橋\",\"position\":\"红灯笼旁边的竖式木牌\"},{\"text\":\"清水寺参道\",\"position\":\"背景中间的竖式白色路牌\"},{\"text\":\"京のおみやげ\",\"position\":\"右侧上方商店的大型横向招牌\"},{\"text\":\"桜うどん\",\"position\":\"右侧商店边缘的竖式招牌\"},{\"text\":\"抹茶ソフト\",\"position\":\"左侧街道下方附近的黑色立牌\"},{\"text\":\"お漬物\",\"position\":\"左侧商店附近的小型竖式招牌\"},{\"text\":\"お物\",\"position\":\"中左侧附近的小型红色挂灯笼\"}]},\"notable_discrete_objects\":{\"count\":12,\"items\":[\"大型红色纸灯笼\",\"小型红色挂灯笼\",\"阳台上的奶油色纸灯笼\",\"人群中的红色遮阳伞\",\"绿色抹茶冰淇淋展示模型\",\"招财猫摆件\",\"达摩玩偶\",\"盒装纪念品甜点\",\"折扇\",\"圆形糖果串\",\"木质阳台茶桌\",\"远处的宝塔\"]},\"composition_notes\":\"使画面密集地填满许多微小的面孔和物体，但要保持沿巷道清晰的视觉路径。利用樱花枝条勾勒屋顶和背景。包含充满微型纪念品的温暖商店内部。增加一些由人头和灯笼造成的自然遮挡，以增强寻物解谜的趣味性，但避免任何遮挡面部或出现黑块的情况。\",\"quality\":\"前景细节锐利，屋顶瓦片和木材纹理复杂，日文招牌清晰可辨，高分辨率，迷人且适合全家欣赏\"}","imgs":["https://r2.qqsrc.com/images/originals/17948.jpg"]},{"i":10005,"text":"{\"type\":\"高度细节化的微缩立体模型寻物旅行解谜插画\",\"theme\":\"北海道黄金周观光场景，可爱的玩具风格 3D Q 版造型\",\"main_goal\":\"创作一张热闹的“寻找角色”图片，观众必须在人群和花丛中找到一只名为 {argument name=\\\"hidden character name\\\" default=\\\"Luhia\\\"} 的微小黄色橡皮鸭角色。\",\"composition\":{\"camera\":\"高处四分之三俯视视角，俯瞰密集的微缩旅游小镇，4:5 竖构图\",\"style\":\"充满奇趣的超细节 3D 渲染，粘土玩具人偶，光泽感眼睛，温暖阳光，浅景深，色彩鲜艳的旅行海报质感\",\"background\":\"晴朗蓝天下的羊蹄山或北海道高山，中景处有札幌电视塔，小型城市建筑和常青树\",\"midground\":\"左侧是樱花环绕的札幌市钟楼，右侧是点亮温暖灯笼的森林精灵露台（Ningle Terrace），大片紫色、黄色、粉色和橙色的富田农场薰衣草与郁金香花田\",\"foreground\":\"拥挤的鹅卵石集市街道，摆放着海鲜丼、螃蟹、牛奶瓶、冰淇淋、奶牛、狸猫吉祥物、篮子、木质摊位、圆灯串，以及许多正在吃东西和拍照的微小游客\"},\"hidden_object\":{\"count\":1,\"description\":\"一只藏在富田农场标志右下角花丛中的小黄鸭，被黄色花朵部分遮挡\",\"must_be_visible\":true},\"characters\":{\"count\":50,\"description\":\"50 个小巧的 Q 版游客人偶散布在桥梁、小船、花田、集市街道和商店区域；大多数是日系可爱的儿童或年轻游客，圆脸，戴着冬帽、头盔，拿着相机、碗、冰淇淋和户外服装；保持姿势和服装的多样性，但比例统一为微缩玩具尺寸\"},\"visible_text_and_signs\":{\"count\":8,\"labels\":[\"{argument name=\\\"puzzle title text\\\" default=\\\"ルヒアを探せ！\\\"}\",\"北海道ソフトクリーム\",\"海鲜丼 いくら・うに・かに\",\"ファーム富田 FARM TOMITA\",\"北海道牛乳ソフトクリーム\",\"ニングルテラス\",\"時計台\",\"SAPPORO\"]},\"specific_objects\":{\"landmarks_count\":4,\"landmarks\":[\"札幌市钟楼\",\"札幌电视塔\",\"森林精灵露台木屋\",\"富田农场花田\"],\"food_stalls_count\":3,\"food_stalls\":[\"左下角的海鲜丼和螃蟹摊位\",\"右下角的牛奶和冰淇淋摊位\",\"左侧巨大的北海道冰淇淋招牌\"],\"animals_count\":4,\"animals\":[\"右下角一个穿奶牛花纹吉祥物服的孩子\",\"牛奶摊位旁的一头黑白奶牛\",\"下部中心附近的一只小狸猫吉祥物\",\"牛奶摊位屋顶上的一只微小松鼠\"],\"vehicles_count\":1,\"vehicles\":[\"运河中载着游客的一艘小木船\"]},\"top_right_badge\":{\"description\":\"奶油色羊皮纸风格的边框标志，左侧有一个小黄鸭图标，右侧是醒目的日文解谜标题\",\"text\":\"{argument name=\\\"puzzle title text\\\" default=\\\"ルヒアを探せ！\\\"}\"},\"lighting_and_color\":\"明亮的春日日光，色彩饱和但自然，樱花粉、薰衣草紫、金色的集市灯光、红色的塔、雪白的群山，营造出引人入胜的旅行冒险氛围\",\"quality\":\"极其精细，前景清晰，微缩比例写实，迷人的收藏级人偶美学，无留白，高密度的寻物解谜布局\"}","imgs":["https://r2.qqsrc.com/images/originals/17949.jpg"]},{"i":10006,"text":"{\"type\":\"高度精细的等距 3D 微缩立体模型找找看插图\",\"theme\":\"在黄金周期间寻找隐藏在大阪的橡皮鸭角色\",\"scene\":{\"location\":\"以道顿堀和新世界为灵感的商业街运河\",\"time\":\"阳光明媚的白天，蓝天白云\",\"mood\":\"节日氛围、拥挤、可爱、俏皮、具有旅行海报的活力\",\"camera\":\"略微俯视的广角视角，俯瞰狭窄的街道和运河，向通天阁方向延伸的深远透视\",\"rendering\":\"gpt-image-2 风格，超精细玩具般的 3D 效果，Q 版人物，光泽感微缩塑料质感，温暖的写实光影，清晰的招牌，鲜艳的红、金、蓝和奶油色\"},\"main_objective\":{\"instruction_panel\":\"右上角的对话框面板，带有黄色橡皮鸭图标和日语文本 {argument name=\\\"search instruction text\\\" default=\\\"ルヒアを探せ！\\\"}\",\"hidden_target\":\"一只名为 {argument name=\\\"hidden character name\\\" default=\\\"ルヒア\\\"} 的微型黄色橡皮鸭吉祥物，可见但容易被忽略，放置在中心前景的人群中，处于儿童高度\",\"search_game_feel\":\"类似《威利在哪里》的视觉解谜，包含数十种干扰元素和可爱的面孔\"},\"crowd\":{\"count\":\"约 140 名 Q 版游客和当地人\",\"description\":\"圆头圆脑的日式动漫风格儿童和成人，拥有光泽的黑色或棕色头发、红润的脸颊、富有表现力的眼睛，穿着休闲的春季旅行服装，背着背包，戴着帽子，拿着相机、零食、章鱼烧盒、冰淇淋、串烧和购物袋\",\"poses\":\"行走、吃东西、挥手、聊天、抬头看招牌、乘船、从阳台上探出身子\"},\"major_landmarks_and_props\":{\"count\":9,\"items\":[\"左侧建筑上巨大的蓝色格力高跑男广告牌\",\"背景远处居中的通天阁\",\"左侧外墙上巨大的红蟹餐厅招牌\",\"右上方外墙上巨大的饺子招牌\",\"街道上方悬挂的巨大圆形白色河豚灯笼\",\"运河中满载 Q 版乘客的黄色观光船\",\"右下角带有红色大阪字样的白色纸灯笼\",\"右下角金色的比利肯风格幸运雕像\",\"挤满观众的小型运河桥梁和栏杆\"]},\"visible_signage\":{\"count\":20,\"labels\":[\"Glico\",\"グリコ\",\"づぼらや\",\"通天阁\",\"I ♥ 通天阁\",\"大阪王将\",\"元祖 焼餃子\",\"くれおーる\",\"たこ焼・お好み焼\",\"横綱\",\"串かつ\",\"名物 串かつ\",\"かに道楽\",\"たこ焼き\",\"道頓堀 DOTONBORI\",\"大阪\",\"新世界\",\"大阪名物\",\"串かつ だるま\",\"ルヒアを探せ！\"]},\"composition\":{\"foreground\":\"街道上密集的 Q 版游客，正在吃大阪街头小吃，街道两侧有纪念品摊位和微型商店陈列\",\"midground\":\"运河穿过场景，有拥挤的黄色观光船和桥梁，许多商店招牌和悬挂的灯笼\",\"background\":\"高耸的大阪霓虹灯区，有通天阁、堆叠的垂直日式招牌、挤满微型人物的阳台\",\"right_top\":\"带有橡皮鸭图标的大型框架搜索说明牌\",\"left_side\":\"显眼的格力高广告牌、红蟹招牌、堆叠的观众阳台\"},\"style_constraints\":{\"detail_level\":\"信息密度极高，每个窗户和商店陈列都填满了微型人物、食物、玩具和招牌\",\"text\":\"日式餐厅招牌在较大的情况下应清晰可辨，采用手绘复古昭和时代风格\",\"lighting\":\"干净的日光，柔和的阴影，饱和的旅行摄影色彩\",\"aspect_ratio\":\"竖向 3:4\",\"avoid\":\"空白区域、写实的人体比例、黑暗的夜景、恐怖氛围、模糊、极简主义\"}}","imgs":["https://r2.qqsrc.com/images/originals/17950.jpg"]},{"i":10007,"text":"创作一张高度写实的生活方式编辑摄影作品，拍摄 {argument name=\"subject\" default=\"一位年轻女性\"} 坐在温馨木质咖啡馆内，靠在一扇大型复古窗户旁的质朴木桌前。她留着深色头发，扎成随意的丸子头，身穿奶油色针织无袖 V 领连衣裙，肩上披着一件浅蓝色牛仔外套，并佩戴精致的金色首饰，包括一条小吊坠项链、手链和戒指。她的姿势放松且沉思，单手托腮，手肘撑在桌面上，身体略微朝向镜头；在面部覆盖一个肤色棕色的不透明方形遮挡块。桌上放置 2 个主要物品：一个带有拉花图案的陶瓷拿铁咖啡杯及托盘，以及一个装有干白花的小玻璃罐。背景呈现 3 个关键咖啡馆元素：左侧透入柔和日光的多格窗框、温暖的深色木质墙板，以及后墙上模糊的黑板菜单。使用 {argument name=\"lens focal length\" default=\"35mm\"} 纪录片风格摄影，浅景深，左侧自然窗光，温暖的室内阴影，柔和的背景虚化，逼真的皮肤和织物纹理，竖构图人像，略微俯视桌面的高机位，柔和的大地色调，温馨的雨天咖啡馆氛围，以及全画幅相机大光圈拍摄的效果。","imgs":["https://r2.qqsrc.com/images/originals/17951.jpg"]},{"i":10008,"text":"{\"type\":\"高度精细的等距 3D 找茬城市场景\",\"title_text\":\"{argument name=\\\"headline text\\\" default=\\\"寻找 Ruhia！\\\"}\",\"setting\":\"东京涩谷黄金周特别场景，阳光明媚，采用类似微缩模型的超高视角广角镜头，背景为蓝天下的东京塔和摩天大楼\",\"main_goal\":\"创作一张“寻找角色”的解谜图片，让观众在密集的 Q 版人群中寻找 Ruhia\",\"style\":\"GPT-image-2 风格，超精细玩具质感 3D 渲染，动漫 Q 版人物，清晰的日光，浅景深微缩效果，鲜艳的商业色彩，密集的城市标牌，俏皮的旅行海报氛围\",\"layout\":{\"camera\":\"高角度广角镜头，俯瞰挤满 Q 版行人的著名涩谷风格十字路口\",\"foreground\":\"斑马线、小型汽车和巴士、树木、路灯、商店入口、成群的 Q 版动漫人物\",\"midground\":\"中央是巨大的 QFRONT 大楼，带有 TSUTAYA 和 STARBUCKS COFFEE 标志，周围环绕着许多垂直的日文招牌和广告牌\",\"background\":\"左侧为涩谷 109 大楼，后方是红色的东京塔，现代办公楼和商业建筑填满了天际线\",\"top_right_overlay\":\"一个带有细红色装饰边框的白色矩形标牌，上面有醒目的黑色日文标题文字和一个黄色小黄鸭图标\"},\"counted_elements\":{\"rubber_ducks\":{\"count\":2,\"items\":[\"一只黄色小黄鸭坐在左上角的 SHIBUYA 109 大楼屋顶上\",\"右上角标题牌内有一个黄色小黄鸭图标\"]},\"major_brand_or_landmark_signs\":{\"count\":17,\"items\":[\"SHIBUYA 109\",\"UNIQLO\",\"H&M\",\"IKEA\",\"QFRONT\",\"STARBUCKS COFFEE\",\"TSUTAYA\",\"Hisamitsu\",\"サロンパス\",\"DHC\",\"109MEN'S\",\"DMM TV\",\"格力高跑男广告牌\",\"竹下通拱门\",\"东京塔\",\"もも原宿广告牌\",\"アイ♡ライブ广告牌\"]},\"headline_placards\":{\"count\":1,\"items\":[\"右上角带边框的标牌，文字为 {argument name=\\\"headline text\\\" default=\\\"寻找 Ruhia！\\\"}，旁边有一只鸭子\"]}},\"characters\":{\"crowd\":\"数百名小巧的动漫 Q 版行人，肩并肩挤在街道和人行道上，拥有各种发色、服装、动物耳朵配饰、小包和偶像风格的服饰\",\"hidden_target\":\"{argument name=\\\"hidden character\\\" default=\\\"Ruhia\\\"} 应伪装在人群中的某个位置，作为搜索游戏的目标\",\"character_style\":\"可爱的圆润 Q 版比例，大头，亮晶晶的眼睛，小巧的身体，玩具手办质感\"},\"signage_and_details\":\"建筑物上布满了色彩缤纷的日文街道招牌、偶像海报、咖啡馆招牌、卡拉 OK 招牌、扭蛋风格装饰、屋顶空调、阳台、窗户和微缩城市杂物；在左下中心处加入一个竹下通风格的装饰拱门，带有可爱的吉祥物装饰\",\"color_palette\":\"晴朗的蓝天、温暖的阳光、饱和的红色、蓝色、黄色、粉色偶像广告牌、灰色混凝土建筑以及五彩缤纷的人群点缀\",\"render_quality\":\"极其密集的细节，清晰可辨的中央标志，逼真的微缩阴影，异想天开但可信的涩谷旅行场景，没有留白区域\"}","imgs":["https://r2.qqsrc.com/images/originals/17952.jpg"]},{"i":10009,"text":"创作一张写实的编辑类生活方式摄影作品，主体为 {argument name=\"subject\" default=\"一位年轻女性\"}，她坐在舒适的复古咖啡馆内一张质朴的木桌旁，身旁是高大的老式窗格，柔和的日光从左侧倾泻而入。她身穿 {argument name=\"outfit\" default=\"一件米色麻花针织中长裙，肩上披着一件浅蓝色超大款牛仔外套\"}，佩戴着精致的项链和手链，坐在深色木椅上，双腿交叠，一只手放在桌上，另一只手轻轻触碰脸颊。她深色的头发随意挽起，留有自然的碎发，但她的面部被一个位于正中央的纯棕色方块刻意遮挡，以实现匿名化。桌上恰好有 2 个可见的桌面道具：右侧边缘附近有一小杯奶泡拿铁，以及一个装有干花和尤加利叶的透明玻璃花瓶。背景中包含 2 个醒目的咖啡馆装饰元素：一块写有“DAILY SPECIALS”字样的深色黑板菜单，上面有模糊的手写价格，以及温暖的垂直木质墙板。采用自然的纪录片摄影风格，具有浅景深、暖木色调、奶油色高光、写实的织物纹理、柔和的窗光、细腻的胶片颗粒感、50mm 镜头视觉、f/2.8 光圈、竖构图人像、私密的咖啡馆氛围、高度写实，无插画或 CGI 感。","imgs":["https://r2.qqsrc.com/images/originals/17953.jpg"]},{"i":10010,"text":"一张写实风格的竖版肖像，展示一位 {argument name=\"subject\" default=\"年轻东亚男性职场人士\"} 坐在现代办公桌前，神情平静，直视镜头，表情柔和中性。他留着 {argument name=\"hair style\" default=\"中长款深棕色层次感发型，略带湿发质感，侧分并留有松散刘海\"}，皮肤白皙细腻，五官精致，外表时尚干练。他身穿 {argument name=\"outfit\" default=\"黑色廓形西装外套，内搭纯白色 T 恤\"}，胸前挂着蓝色挂绳和清晰可见的员工工牌。他的双手放在一台深空灰色笔记本电脑的键盘上，电脑左侧的桌面上放着黑色 Apple 标志。桌面上除了笔记本电脑外，还有 3 件清晰可见的物品：正前方中央放着一部正面朝上的黑色智能手机，右侧放着一本白色螺旋笔记本，笔记本上斜放着一支黑色钢笔。背景为明亮的玻璃墙企业办公室，带有模糊的办公桌、窗户、隔断和冷色调日光，浅景深，逼真的反射效果，采用柔和的灰蓝色调，光线柔和漫射，高端编辑摄影风格，85mm 镜头质感，自然的皮肤纹理，面部焦点清晰，2:3 竖构图，营造出专业又不失时尚的氛围。","imgs":["https://r2.qqsrc.com/images/originals/17954.jpg"]},{"i":10011,"text":"创作一张高级时尚赛博朋克杂志封面，展示一张年轻女性在霓虹闪烁的首都城市夜晚的街头风格特写肖像。她留着长而浓密的赛博编发，由光泽感黑色光纤电缆制成，带有蓝色、紫色和洋红色的高光，配有金属连接环，耳边有一个圆形科技装饰。她的脸部被一个柔和棕紫色的方形像素化隐私遮挡块有意遮盖。她身穿黑色罗纹系带上衣、宽松的露肩黑色皮夹克，以及带有面板细节的宽大未来感铬合金颈圈。她的一只手拿着一个小巧的透明赛博终端或类似智能手机的设备，上面有发光的蓝色界面图形，连接的电缆延伸到她的服装中。背景是下雨的城市夜街，有潮湿的反射路面、模糊的行人、高耸的建筑以及色彩斑斓的失焦广告牌和标志，采用浅景深、电影级散景、光泽反射和逼真的编辑级灯光进行拍摄。将其设计为时尚杂志封面，包含 3 个精确的文本元素：左上角巨大的细体白色刊头，文字为 {argument name=\"magazine title\" default=\"NEURO\"}；右上角两行简短的标题，文字为 {argument name=\"cover caption\" default=\"FASHION SNAP\\nCAPITAL CITY NIGHT\"}；左下角微小的期号/日期标记，文字为 {argument name=\"issue text\" default=\"2126 / SPRING\"}。采用竖版封面构图，高级赛博时尚美学，照片级逼真细节，冷色调蓝紫色霓虹配色，以及清晰的排版。","imgs":["https://r2.qqsrc.com/images/originals/17955.jpg"]},{"i":10012,"text":"创作一幅温暖、舒适的动漫风格插画，描绘 {argument name=\"character description\" default=\"一只快乐的拟人化三花猫\"} 在阳光充足的卧室里享受慵懒假日午后的场景。角色斜倚在柔软的奶油色床上，身穿 {argument name=\"outfit\" default=\"一件纯白 T 恤和宽松的灰色抽绳运动裤\"}，戴着圆形金属框眼镜，闭着双眼微笑着，一只手枕在脑后，另一只手拿着一杯泡沫丰富的 {argument name=\"drink\" default=\"金色啤酒\"}。添加一条卷曲在床上的三花猫尾巴、清晰可见的脚掌肉垫、淡淡的红晕以及放松的肢体语言。房间应营造出宁静且充满生活气息的氛围，左侧大开的窗户透进金色的阳光，窗外是蓝天和蓬松的云朵，窗台和前景处摆放着绿植。在角色身后放置两个枕头，一个为芥末黄，另一个为绿色格子图案，搭配奶油色床品和圆润的木质床头板。在床头墙面上，包含三个墙面装饰：一张写有 {argument name=\"poster text\" default=\"GOOD DAY\"} 的猫咪海报、一个带有猫爪印的“Relax”小挂牌，以及一幅风景画框。在右上方的墙面搁板上，包含五个可见物品：一盆垂吊植物、一个猫脸毛绒玩具或装饰品、两本立着的书，以及一个风景照片框。在右侧放置一个床头柜，上面有台灯、小闹钟和一个杯子；在角色附近的床上放置一个打开的饮料罐。在前景处，放置一张矮桌，上面有一杯茶和一本名为 {argument name=\"magazine title\" default=\"NEKO LIFE\"} 的杂志，封面上印有猫咪插画，旁边还有一盆小绿植。采用柔和的绘画式阴影、细腻的线条、温暖的米色和蜂蜜色调，展现精致的温馨杂物、斑驳的阳光以及轻松的生活片段氛围。","imgs":["https://r2.qqsrc.com/images/originals/17956.jpg"]},{"i":10013,"text":"创作一个暗黑电影级写实风格的乡村科幻场景，采用 4:5 竖构图。前景中，一个 {argument name=\"girl age\" default=\"小女孩\"} 背对观众站在泥泞的土路上，居中站立，望向地平线；她留着深棕色的松散辫子，身穿灰色针织毛衣、一条 {argument name=\"skirt color\" default=\"深红色花纹裙子\"}、黑色连裤袜和磨损的深色靴子。道路在干枯的棕色草丛和灌木丛中微微向上蜿蜒。左侧中景处坐落着一座古老的小石屋，有着粗糙的灰色砖墙、红陶瓦屋顶、烟囱、深色木门、一扇小窗和一道低矮的石墙，旁边有一棵枯树。右侧背景中耸立着一个巨大的古代机器人，高度约为小屋的十倍，人形且饱经风霜，由深色腐蚀的金属板构成，关节处悬挂着裸露的电缆，肩膀宽大，手臂沉重，双腿粗壮，头部呈骷髅状并带有圆形眼睛，顶部有一根细长的天线尖刺；它在迷雾中一动不动，面向女孩。氛围阴郁且具有末日感，厚重的炭灰色风暴云覆盖了大部分天空，戏剧性的漫射光穿过云层缝隙，色调为柔和的大地色，高对比度，颗粒感纹理，真实的景深，低地平线，广角电影视角，情绪化的电影调色，无文字，无边框。","imgs":["https://r2.qqsrc.com/images/originals/17957.jpg"]},{"i":10014,"text":"{\"type\":\"日本时尚产品概念艺术图\",\"format\":\"暖米白色纸张上的单页垂直概念项目\",\"overall_style\":\"柔和水彩与铅笔插画，精致的手绘时尚设计渲染，柔和的米色背景渲染，精细的墨水注释，编辑类概念艺术排版，柔和的自然光，高端生活方式品牌感\",\"language\":\"可见日文标题和注释\",\"main_subject\":{\"character\":\"年轻女性模特，面部特征通过平滑的肤色矩形遮罩刻意模糊，无可见的眼睛或嘴巴\",\"hair\":\"{argument name=\\\"hair color\\\" default=\\\"深棕色\\\"} 头发中分并扎成低位的凌乱发髻\",\"outfit\":\"{argument name=\\\"outfit description\\\" default=\\\"白色泡泡袖衬衫配蕾丝前襟，粉色背带连衣裙配百褶短裙，白色短袜，米色玛丽珍鞋\\\"}\",\"pose\":\"优雅站立，脸旁拿着一台轻薄平板，营造出从校园到生活方式的平静友好品牌氛围\"},\"product\":{\"device\":\"{argument name=\\\"device name\\\" default=\\\"Hassbald\\\"} 轻薄平板\",\"appearance\":\"简约时尚的金属灰平板，圆角设计，小摄像头点，背面有精致 Logo\",\"theme\":\"未来学习设备，感觉亲近、温和且易于使用\"},\"layout\":{\"title_area\":{\"position\":\"左上\",\"main_title\":\"コンセプトアート\",\"subtitle\":\"未来の学びを、やさしく身近に。\",\"notes\":\"标题下方的小型手写日文概念文案\"},\"centerpiece\":\"身穿粉色连衣裙的女性全身正面照，头部附近竖直拿着平板\",\"large_left_illustration\":\"同一女性拿着灰色平板靠近脸部的半身肖像剪裁，占据页面左半部分\",\"right_top_portrait\":\"同一角色的头部和肩部研究，面部模糊，低发髻发型，周围有米色笔触渲染\",\"right_middle_device_panel\":{\"title\":\"デバイスデザイン\",\"position\":\"中右\",\"count\":1,\"labels\":[\"シンプル\",\"薄型\",\"高級感のあるメタリックカラー\"]},\"right_middle_outfit_panel\":{\"title\":\"衣装デザイン\",\"position\":\"中右下方\",\"count\":1,\"labels\":[\"白シャツで清潔感と知性を\",\"ピンクのサスペンダースカートで親しみやすさをプラス\",\"動きやすく若々しい印象に\"]},\"back_view_panel\":\"小型背面时尚素描，展示了白色衬衫和百褶裙上交叉的粉色背带，系成蝴蝶结\",\"rough_sketch_panel\":{\"title\":\"ラフ案\",\"position\":\"右下\",\"count\":4,\"labels\":[\"front pose holding tablet\",\"front pose relaxed\",\"back pose holding tablet\",\"plain back pose\"]},\"keyword_panel\":{\"title\":\"キーワード\",\"position\":\"左下\",\"count\":5,\"labels\":[\"信頼\",\"知性\",\"やさしさ\",\"未来感\",\"親近感\"]},\"color_palette\":{\"title\":\"カラーパレット\",\"position\":\"左下\",\"count\":5,\"swatches\":[\"ピンク（親しみ・やさしさ）\",\"ホワイト（清潔感）\",\"ベージュ（柔らかさ）\",\"グレー（信頼・未来感）\",\"ゴールド（上品さ）\"]},\"concept_box\":{\"title\":\"コンセプト\",\"position\":\"底部中心\",\"text\":\"{argument name=\\\"concept quote\\\" default=\\\"未来の学びを、やさしく身近に。テクノロジーをもっとやさしく、もっと親しみやすく。そんな想いを、彼女の笑顔とデザインに込めました。\\\"}\"},\"brand_lockup\":{\"position\":\"右下\",\"text\":\"{argument name=\\\"brand name\\\" default=\\\"Hassbald\\\"}\",\"subtext\":\"Brand Concept Art\",\"decoration\":\"小型橄榄枝线条艺术\"}},\"composition_details\":\"细边框角标，零散的铅笔引导线，手写日文注释，人物背后柔和的腮红和米色水彩笔触，平衡的杂志风格产品设计项目；保持所有文字清晰可辨，并像专业的概念艺术演示一样排列\"}","imgs":["https://r2.qqsrc.com/images/originals/17958.jpg"]},{"i":10015,"text":"{\n  \"type\": \"电影感动漫电影海报\",\n  \"format\": \"垂直院线单张海报，高对比度，光面印刷质感\",\n  \"main concept\": \"一张结合了 007 枪管螺旋视角、春日樱花美景与孤身女学生主角的间谍惊悚校园剧海报\",\n  \"title text\": {\n    \"large Japanese title\": \"{argument name=\\\"Japanese title text\\\" default=\\\"私立 あかつき学園\\\"}\",\n    \"English title\": \"{argument name=\\\"English title text\\\" default=\\\"THE SPY WHO FORGOT THE BONDS\\\"}\",\n    \"subtitle\": \"ー命と絆とスパイー\",\n    \"bottom tagline\": \"{argument name=\\\"bottom tagline\\\" default=\\\"この春、ここから始まる。\\\"}\",\n    \"vertical tagline\": \"{argument name=\\\"vertical tagline\\\" default=\\\"この春、音が侵食する。\\\"}\",\n    \"credit line\": \"监督：サブサン　脚本：chat gpt＋claude　角色设计：gpt image 2.0　出演：君唯ひなた　上师京子　他\"\n  },\n  \"subject\": {\n    \"count\": 1,\n    \"description\": \"一名动漫高中女生侧影，在海报中心从左向右行走，短碎棕发，表情严肃冷静，身穿海军蓝短袖校服西装、白衬衫、红领带、红格子裙、深色及膝袜、黑色乐福鞋，倒映在湿润的光面地板上\",\n    \"pose\": \"侧面行走姿态，双臂自然下垂，坚定且具有电影感的剪影\"\n  },\n  \"background\": {\n    \"central aperture\": \"巨大的圆形枪管开口，框住春日的城市景观\",\n    \"gun barrel\": \"黑色与枪金属色的螺旋膛线环向内卷曲，锐利的高对比度弧线，带有金属划痕质感\",\n    \"inside circle\": \"日落时分的东京天际线，背景有粉色樱花，右侧可见东京塔，下方为河流或反光广场，天空为柔和的蓝粉色黄昏色调\",\n    \"outer field\": \"深海军蓝与黑色的间谍电影氛围，左侧带有红色余烬般的颗粒，右侧带有电光蓝色的光束\"\n  },\n  \"petals and particles\": {\n    \"cherry blossom petals\": \"大量粉色花瓣斜向飘过整个画面，前景中有部分带有动态模糊的大花瓣\",\n    \"effects\": \"红色火花、蓝色光束、烟雾颗粒、电影感尘埃、戏剧性的光晕效果\"\n  },\n  \"layout\": {\n    \"text blocks count\": 6,\n    \"text blocks\": [\n      {\"position\": \"顶部中心，垂直\", \"content\": \"この春、音が侵食する。\", \"style\": \"白色垂直日文文本，其中“音”和“侵食”二字为红色\"},\n      {\"position\": \"左下至中心\", \"content\": \"私立 あかつき学園\", \"style\": \"巨大的裂纹做旧日文字体，顶部字符较小且为白色，主字符为红色，末尾字符为蓝色，带有黑色阴影和金属轮廓\"},\n      {\"position\": \"底部中心\", \"content\": \"THE SPY\", \"style\": \"大型做旧白色模板块状字母，P 字母内嵌红色瞄准准星\"},\n      {\"position\": \"右下\", \"content\": \"WHO FORGOT THE BONDS\", \"style\": \"堆叠式白色做旧压缩无衬线字体\"},\n      {\"position\": \"标题下方\", \"content\": \"ー命と絆とスパイー\", \"style\": \"小型白色日文副标题\"},\n      {\"position\": \"底部中心\", \"content\": \"この春、ここから始まる。\", \"style\": \"加粗白色日文标语\"}\n    ],\n    \"composition\": \"角色位于标题上方的圆形开口中心；标题占据底部三分之一；枪管产生强烈的径向焦点；演职员表位于底部标语上方\"\n  },\n  \"style\": \"日本动漫电影海报，戏剧性间谍动作排版，精致的宣传主视觉图，超细节，电影级灯光，清晰的线条艺术，绘画感背景，逼真的反射效果，4K 海报画质\",\n  \"color palette\": \"黑色、枪金属灰、樱花粉、日落薰衣草紫、深红色、电光蓝、做旧白\",\n  \"avoid\": \"多余角色、模糊标题、无法辨认的主文字、低分辨率排版、水印、Logo、照片级写实人类\"\n}","imgs":["https://r2.qqsrc.com/images/originals/17959.jpg"]},{"i":10016,"text":"{\"type\":\"手绘动漫角色复刻速查表，用于保持 LINE 贴图生成的一致性\",\"overall_style\":\"干净的白纸参考表，黑色手绘边框，随意的日式马克笔手写字，柔和的平涂色彩，简约的漫画线条，亲切且略显朴素的设计，教育类排版，无背景装饰\",\"page_text\":{\"main_title\":\"キャラクター再現チートシート\",\"subtitle\":\"角色及视觉调性复刻 / 保持一致性的设定资料\"},\"character\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"未命名的亲切女孩\\\"}\",\"age_impression\":\"年轻女性或少女，平易近人且普通\",\"hair\":{\"color\":\"{argument name=\\\"hair color\\\" default=\\\"暖浅棕色\\\"}\",\"style\":\"短波波头，有刘海，轮廓圆润，发梢略微内扣至耳边\"},\"face\":\"圆脸轮廓，小巧简约的眼睛和嘴巴，表情温和，面部细节极简\",\"outfit\":\"{argument name=\\\"outfit\\\" default=\\\"纯白 T 恤和蓝色牛仔裤\\\"}\",\"tone\":\"简约、线条粗犷、朴素自然、有亲和力，不过度装饰\"},\"layout\":{\"format\":\"单页垂直 A4 风格表格，分为七个带彩色圆圈编号的方框区域\",\"sections\":[{\"number\":\"①\",\"title\":\"主要角色信息\",\"position\":\"左上\",\"count\":1,\"contents\":\"左侧为角色大头半身像；右侧为要点笔记\",\"visible_bullets\":[\"短波波头\",\"有刘海\",\"圆润轮廓\",\"小巧简约的五官\",\"亲切且易产生共鸣\",\"略显笨拙但坦率的氛围\",\"不华丽，朴素自然\"]},{\"number\":\"②\",\"title\":\"不同角度\",\"position\":\"右上\",\"count\":4,\"labels\":[\"正面\",\"斜侧（3/4）\",\"侧脸\",\"微仰视\"],\"contents\":\"四个头部及肩部角度示例，展示正面、斜侧、侧面以及微仰视的微笑视角\"},{\"number\":\"③\",\"title\":\"表情模式（6 种）\",\"position\":\"中间通栏\",\"count\":6,\"labels\":[\"普通微笑\",\"困惑\",\"礼貌微笑\",\"轻微惊慌\",\"无表情\",\"如释重负\"],\"contents\":\"六个并排的小头像，每个都有不同的简约面部表情\"},{\"number\":\"④\",\"title\":\"动作姿势迷你（复刻样本）\",\"position\":\"左下中\",\"count\":4,\"labels\":[\"站姿\",\"坐姿\",\"轻微招手\",\"歪头\"],\"contents\":\"四个全身姿势小样本：站立、盘腿坐、轻微招手、歪头思考\"},{\"number\":\"⑤\",\"title\":\"设计要点笔记\",\"position\":\"右下中\",\"count\":5,\"visible_bullets\":[\"头发：短波波头，有刘海，注重圆润感\",\"脸部：圆轮廓，较小的眼睛和嘴巴\",\"氛围：亲切、坦率、柔和\",\"线条：以粗且均匀的线条为基础\",\"刻画：极简，简单化\",\"视觉调性：笨拙而亲切的氛围\"]},{\"number\":\"⑥\",\"title\":\"NG 模式（避免的方向）\",\"position\":\"左下\",\"count\":6,\"labels\":[\"凌乱阴郁遮脸的头发\",\"过于华丽闪亮的头发\",\"仅背影\",\"过于精致的偶像式微笑\",\"身体比例过高且写实\",\"Q 版比例过于幼稚\"],\"contents\":\"六个错误的示例，每个样本上方标有黑色 X 号\"},{\"number\":\"⑦\",\"title\":\"按此方向绘制\",\"position\":\"右下\",\"count\":1,\"contents\":\"最终确认的微笑特写，带有绿色勾选清单\",\"visible_checklist\":[\"简约\",\"粗线条\",\"略显笨拙\",\"注重亲切感\",\"注重圆润感\",\"注重视觉调性\"]}]},\"rendering_instructions\":\"创建一份完整的、可读的日文参考表，结构与上述一致。使用 1 到 7 的彩色圆圈编号，黑色矩形边框，手写风格的日文文本，并在整张表中保持角色画风的一致性。保持画作简约、温暖，适合贴图使用。该表应作为在多个 LINE 贴图中复刻同一个角色的实用一致性指南。\",\"custom_text\":\"使用主标题 {argument name=\\\"headline text\\\" default=\\\"キャラクター再現チートシート\\\"}，并保持所有区域标签清晰可见。\"}","imgs":["https://r2.qqsrc.com/images/originals/17960.jpg"]},{"i":10017,"text":"{\"type\":\"LINE 贴纸素材 / 表情包贴纸集\",\"style\":\"可爱的日系 Q 版手绘风格，清晰的黑色轮廓，柔和的平涂色彩，简洁的白色背景，圆润友好的比例，透明贴纸质感，手写风格的粗体黑色毛笔字日语标题\",\"character\":{\"description\":\"每个贴纸中均为同一位年轻女孩，浅棕色短波波头配斜刘海，皮肤白皙，黑色豆豆眼，小巧生动的嘴巴，红润的脸颊\",\"outfit\":\"纯白色短袖 T 恤，根据姿势搭配蓝色牛仔裤或蓝色短裙，全身照时穿着简单的白色运动鞋\",\"hair color\":\"{argument name=\\\"hair color\\\" default=\\\"浅棕色\\\"}\"},\"layout\":{\"format\":\"3x3 的九宫格布局，九个独立的贴纸插画，在白色画布上均匀分布，每个贴纸的标题位于角色上方\",\"count\":9,\"stickers\":[{\"position\":\"左上\",\"caption\":\"{argument name=\\\"sticker text 1\\\" default=\\\"大丈夫？\\\"}\",\"pose\":\"女孩双手合十放在胸前，神情担忧，眉毛上挑，脸旁有一滴小汗珠\"},{\"position\":\"中上\",\"caption\":\"{argument name=\\\"sticker text 2\\\" default=\\\"いいね！\\\"}\",\"pose\":\"女孩右手竖起大拇指点赞，拇指旁有橙色强调符号，表现出愉快的赞同姿势\"},{\"position\":\"右上\",\"caption\":\"{argument name=\\\"sticker text 3\\\" default=\\\"わかる…\\\"}\",\"pose\":\"女孩闭眼温柔微笑，一手托腮，另一只手臂交叉，头部附近有蓝色的共鸣符号\"},{\"position\":\"左中\",\"caption\":\"たしかに\",\"pose\":\"女孩闭眼双臂交叉冷静站立，身旁有绿色的小点头符号\"},{\"position\":\"正中\",\"caption\":\"なるほど\",\"pose\":\"女孩张嘴惊讶，竖起一根食指，手指旁有橙色感叹号\"},{\"position\":\"右中\",\"caption\":\"ほんと？\",\"pose\":\"女孩双手托腮，神情好奇，头旁有一个红色问号\"},{\"position\":\"左下\",\"caption\":\"今向かってます\",\"pose\":\"全身奔跑的女孩向右移动，双臂摆动，身后有蓝色运动线条，可见白色运动鞋\"},{\"position\":\"中下\",\"caption\":\"確認します\",\"pose\":\"女孩一手托腮，另一只手臂交叉思考，表情略显困惑，带有蓝色强调符号\"},{\"position\":\"右下\",\"caption\":\"よろしくです\",\"pose\":\"女孩闭眼礼貌鞠躬，双手合十放在身前，两侧有橙色礼貌强调符号\"}]},\"composition\":\"每个角色位于标题下方居中，无边框或分格，留白充足，比例统一（左下奔跑姿势为全身照除外），清晰的贴纸成品画风\",\"rendering\":\"高分辨率方形图像，可爱的日系聊天贴纸美学，极简阴影，无复杂背景\"}","imgs":["https://r2.qqsrc.com/images/originals/17961.jpg"]},{"i":10018,"text":"{\"type\":\"LINE 贴纸合集插画\",\"style\":\"可爱简洁的日式贴纸艺术，简约手绘动漫风格，粗黑色轮廓，柔和水彩质感上色，白色背景，方形画布\",\"layout\":{\"grid\":\"3 列 3 行\",\"count\":9,\"spacing\":\"均匀间距，每个贴纸清晰分隔\",\"text\":\"每个角色上方均有大型手写黑色日语问候文字，圆润笔触\",\"stickers\":[{\"position\":\"左上\",\"label\":\"おはよう\",\"description\":\"年轻女孩微笑并用右手挥手，挥手旁有橙色强调符号\"},{\"position\":\"中上\",\"label\":\"こんにちは\",\"description\":\"年轻女孩单手挥手；脸部被柔和的方形模糊遮挡块覆盖\"},{\"position\":\"右上\",\"label\":\"おつかれさま\",\"description\":\"年轻女孩闭眼温柔微笑，双手合十放在胸前，侧面有黄色强调符号\"},{\"position\":\"左中\",\"label\":\"おねがいします\",\"description\":\"年轻女孩礼貌鞠躬，闭眼，双手置于身前，头部旁有蓝色动作线\"},{\"position\":\"正中\",\"label\":\"はーい\",\"description\":\"开朗的年轻女孩高举一只手臂，张嘴开心地笑，带有黄色强调符号\"},{\"position\":\"右中\",\"label\":\"了解です\",\"description\":\"年轻女孩单手敬礼，眨眼，带有小型绿色强调符号\"},{\"position\":\"左下\",\"label\":\"ありがとう\",\"description\":\"年轻女孩闭眼灿烂微笑，双手感激地合十，带有粉色强调符号\"},{\"position\":\"中下\",\"label\":\"どういたしまして\",\"description\":\"年轻女孩单手放在胸前；脸部被柔和的方形模糊遮挡块覆盖\"},{\"position\":\"右下\",\"label\":\"すみません\",\"description\":\"年轻女孩表情担忧且抱歉，双手合十，头部旁有小型蓝色汗滴\"}]},\"character\":{\"gender\":\"年轻女孩\",\"age\":\"童年至青春期早期\",\"hair\":\"{argument name=\\\"hair color\\\" default=\\\"浅棕色\\\"} 短波波头，直刘海，两侧有少量鬓发\",\"face\":\"圆润可爱的脸庞，红润脸颊，根据姿势呈现简单的点状眼或闭眼微笑\",\"outfit\":\"{argument name=\\\"outfit\\\" default=\\\"纯白色短袖 T 恤和蓝色牛仔裤\\\"}\"},\"customization\":{\"sticker theme\":\"{argument name=\\\"sticker theme\\\" default=\\\"LINE 贴纸常用日语问候语\\\"}\",\"character name\":\"{argument name=\\\"character name\\\" default=\\\"友好的波波头女孩\\\"}\",\"background color\":\"{argument name=\\\"background color\\\" default=\\\"白色\\\"}\"},\"rendering\":\"高分辨率平面插画，简洁的贴纸构图，无阴影，无边框，9 个姿势中角色设计保持一致，表情生动，带有极简彩色强调符号\"}","imgs":["https://r2.qqsrc.com/images/originals/17962.jpg"]},{"i":10019,"text":"{\"type\":\"LINE 贴纸合集插画\",\"format\":\"单张正方形画布，以整洁的 3x3 网格展示 9 个独立的贴纸设计\",\"style\":\"可爱的日系手绘动漫/漫画风格，简单的黑色轮廓，柔和的平涂色彩，白色背景，亲切随意的日常感，所有贴纸中的角色保持一致，每个贴纸上方均配有粗体手写日文\",\"character\":{\"description\":\"年轻女孩角色，齐肩浅棕色波波头，刘海，圆脸，小圆点眼睛，红润脸颊，白色短袖 T 恤，腰部可见蓝色牛仔裤或蓝色短裙\",\"hair color\":\"{argument name=\\\"hair color\\\" default=\\\"浅棕色\\\"}\",\"shirt\":\"{argument name=\\\"shirt color\\\" default=\\\"白色\\\"}\",\"expression style\":\"简洁可爱的 Q 版面部特征，带有温暖的腮红\"},\"layout\":{\"background\":\"纯白色背景，贴纸之间留有充足间距\",\"grid\":{\"rows\":3,\"columns\":3,\"total stickers\":9},\"stickers\":[{\"position\":\"左上\",\"label\":\"ただいま\",\"meaning\":\"我回来了\",\"pose\":\"正面半身微笑，双臂自然下垂，角色身旁有小型橙色强调符号\"},{\"position\":\"中上\",\"label\":\"おかえり\",\"meaning\":\"欢迎回来\",\"pose\":\"正面角色单手挥动，欢快的问候，抬起的手旁有橙色强调符号\"},{\"position\":\"右上\",\"label\":\"お先に失礼します\",\"meaning\":\"我先走了\",\"pose\":\"礼貌鞠躬，闭眼，双手合十于身前，头部旁有小型蓝色动作符号\"},{\"position\":\"左中\",\"label\":\"またね\",\"meaning\":\"再见\",\"pose\":\"大大的闭眼微笑，单手挥动，手旁有橙色强调符号\"},{\"position\":\"正中\",\"label\":\"おやすみ\",\"meaning\":\"晚安\",\"pose\":\"困倦平和的表情，闭眼，双手合十贴在脸颊旁，右侧有黄色新月和两颗黄色星星\"},{\"position\":\"右中\",\"label\":\"ねむい…\",\"meaning\":\"好困……\",\"pose\":\"打哈欠，单手遮嘴，眼睛半闭，头部旁有两个蓝色睡眠气泡\"},{\"position\":\"左下\",\"label\":\"ごめんね\",\"meaning\":\"对不起\",\"pose\":\"担忧抱歉的表情，双手合十于胸前，头部旁有蓝色汗滴符号\"},{\"position\":\"中下\",\"label\":\"ＯＫです\",\"meaning\":\"好的\",\"pose\":\"微笑眨眼，单手做出 OK 手势，抬起的手旁有小型绿色强调符号\"},{\"position\":\"右下\",\"label\":\"助かります！\",\"meaning\":\"帮大忙了！\",\"pose\":\"感激的表情，双手合十于胸前，头部两侧有红色强调符号\"}]},\"text\":{\"font\":\"粗体圆润的手写日文字体，黑色，放置在每个角色上方\",\"labels\":\"使用这 9 个指定的日文短语：ただいま, おかえり, お先に失礼します, またね, おやすみ, ねむい…, ごめんね, ＯＫです, 助かります！\",\"custom phrase set\":\"{argument name=\\\"sticker phrases\\\" default=\\\"ただいま / おかえり / お先に失礼します / またね / おやすみ / ねむい… / ごめんね / ＯＫです / 助かります！\\\"}\"},\"composition notes\":\"保持每个贴纸独立且间距均匀，所有 9 个姿势中的角色比例和服装保持一致，无阴影或复杂背景，适合作为可爱的日系 LINE 贴纸包预览\",\"rendering\":\"高分辨率清晰数字插画，文字清晰易读，色彩柔和温暖，道具极简\"}","imgs":["https://r2.qqsrc.com/images/originals/17963.jpg"]},{"i":10020,"text":"{\"type\":\"日本电车吊挂广告风格动漫电影海报及原创小说概念艺术\",\"format\":\"横向 4:3 剧场版主视觉图，光面商业印刷设计，密集排版，戏剧性的学校音乐教室背景\",\"setting\":{\"location\":\"阳光明媚的日本高中音乐教室\",\"details\":\"左侧大窗户，窗外可见蓝天与城市绿植，米色窗帘，木地板，黑板上有五线谱，黑板上方正中挂着挂钟，左后方有书架和黑色音箱，前景有钢琴和乐谱架，温暖的午后光线\"},\"main cast\":{\"count\":3,\"characters\":[{\"position\":\"左侧\",\"description\":\"身穿海军蓝西装校服、系红领带、白衬衫、百褶裙、过膝袜的少女，黑色双马尾系着红丝带，正拉着小提琴，动作坚定\"},{\"position\":\"中央\",\"description\":\"身穿黑色西装外套和白衬衫的成年女性教师或监护人，棕色齐肩短发，自信地站着弹奏木吉他\"},{\"position\":\"右侧\",\"description\":\"身穿海军蓝西装校服、系红领带并佩戴校徽的少年，黑色乱发，吹奏着金色小号，姿态英勇挺拔\"}],\"face treatment\":\"面部刻意模糊/遮挡，如同概念草图，但身体和服装保持清晰\",\"instruments\":{\"count\":3,\"items\":[\"小提琴\",\"木吉他\",\"小号\"]}},\"typography\":{\"main title\":{\"position\":\"前景中央大字\",\"text\":\"私立あかつき学園\",\"style\":\"巨大的做旧块状日文书法，白色与血红色，黑色描边，带有裂纹的颓废质感，红色中心文字后方带有瞄准镜图形\"},\"english title\":{\"position\":\"日文主标题下方\",\"text\":\"THE SPY\",\"style\":\"超大号做旧白色模板字体，黑色描边\"},\"english subtitle\":{\"position\":\"THE SPY 右侧\",\"text\":\"WHO FORGOT THE BONDS\",\"style\":\"紧凑的白色粗体堆叠排版\"},\"japanese subtitle\":{\"position\":\"标题下方\",\"text\":\"ー命と絆とスパイー\",\"style\":\"小型白色电影感副标题\"}},\"layout\":{\"sections\":[{\"title\":\"左上角标语\",\"position\":\"左上方红色撕裂感横幅\",\"count\":1,\"labels\":[\"夺回被夺走的人生。\\n那份羁绊，足以撼动世界。\"]},{\"title\":\"右侧竖排标语\",\"position\":\"右上方小号手旁\",\"count\":1,\"labels\":[\"音乐所连接的，\\n唯一的家人。\"]},{\"title\":\"上映日期徽章\",\"position\":\"左下角红色圆形徽章\",\"count\":1,\"labels\":[\"2025 年\",\"10.10\",\"周五\",\"公映\"]},{\"title\":\"演职员表框\",\"position\":\"右下角金色边框黑色矩形\",\"count\":5,\"labels\":[\"原作：サブサン\",\"导演：サブサン\",\"编剧：Chat GPT+Claude\",\"音乐：SUNO\",\"官方网站：akatsuki-spy.jp\"]},{\"title\":\"底部公告栏\",\"position\":\"底部全宽深红色长条\",\"count\":3,\"labels\":[\"少年的青春间谍动作片，开幕！\",\"主题曲：私立あかつき学園之主题\",\"点击此处访问官网\"]},{\"title\":\"二维码区域\",\"position\":\"右下角\",\"count\":1,\"labels\":[\"黑白二维码\"]}]},\"color and style\":\"高细节现代动漫插画融合日本电影海报平面设计，饱和的海军蓝校服，红色点缀，金色小号，温暖的教室棕色调，戏剧性的对比度，颓废风动作排版，专业的电车吊挂广告构图\",\"customization\":{\"school name\":\"{argument name=\\\"school name\\\" default=\\\"私立あかつき学園\\\"}\",\"movie title\":\"{argument name=\\\"movie title\\\" default=\\\"THE SPY\\\"}\",\"release date\":\"{argument name=\\\"release date\\\" default=\\\"2025 年 10.10 周五\\\"}\",\"main tagline\":\"{argument name=\\\"main tagline\\\" default=\\\"夺回被夺走的人生。\\\\n那份羁绊，足以撼动世界。\\\"}\",\"website\":\"{argument name=\\\"website\\\" default=\\\"akatsuki-spy.jp\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/17965.jpg"]},{"i":10021,"text":"{\"type\":\"six-panel vertical manga page\",\"language\":\"Japanese visible dialogue and signage\",\"style\":\"soft semi-realistic anime manga, pastel glow, cinematic lighting, delicate linework, transparent holographic UI, magical sparkles, warm shopping-mall interior, clean readable Japanese typography\",\"canvas\":\"portrait page with six bordered panels arranged in a 2-column by 3-row grid, each panel numbered in a white circle at the top-left from 1 to 6\",\"setting\":{\"location\":\"entrance of a glossy event venue and shopping-mall atrium\",\"main sign\":\"{argument name=\\\"venue name\\\" default=\\\"NEONVEIL\\\"}\",\"details\":\"large curved glass entrance canopy, illuminated NEONVEIL sign, vertical digital signboard reading NEONVEIL Welcome Day with schedule-like small text, plants, polished floors, escalator-like architecture, banner showing five idol members above the entrance\"},\"characters\":{\"mascot\":{\"name\":\"{argument name=\\\"mascot name\\\" default=\\\"ネオン君\\\"}\",\"appearance\":\"small floating chibi guide mascot, translucent lavender-white body, round bear-like ears, fluffy short hair, large cyan eyes when visible, tiny plush-like limbs, curled tail, glowing outline, star-shaped decorations, magical aura and sparkles, friendly expressions and welcoming poses\"},\"visitor group\":\"family-like group seen from behind: adult man, small child, adult woman in long blue skirt with shoulder bag, and a wheelchair user moving toward the entrance\",\"female visitor\":\"young woman with long brown hair, cream blouse, blue skirt, shoulder bag, shy or curious posture\"},\"recurring elements\":{\"holographic ticket guide\":\"blue transparent rectangular UI explaining smartphone ticket flow with three counted steps: STEP 1 ticket open, STEP 2 QR scan, STEP 3 admission complete; includes ticket icon, QR code icon, checkmark icon\",\"idol banner\":\"five male idol portraits displayed above the venue entrance\",\"sparkles\":\"white star glints and lavender magical particles around mascot and speech bubbles\"},\"layout\":{\"panel count\":6,\"panels\":[{\"number\":1,\"position\":\"top-left\",\"scene\":\"wide establishing shot of the NEONVEIL entrance; the visitor group approaches from behind toward the glowing venue sign, idol banner, digital signboard, and a floating holographic smartphone-ticket instruction card\",\"visible text\":[\"NEONVEIL\",\"ようこそ NEONVEILへ！スマホチケットをご準備ください♪\",\"STEP 1 チケットを開く\",\"STEP 2 QRをかざす\",\"STEP 3 入場完了!\",\"NEONVEILへ、ようこそ。\"]},{\"number\":2,\"position\":\"top-right\",\"scene\":\"closer view at the entrance with the mascot appearing large in front of the holographic ticket UI, sparkling and greeting visitors; idol banner remains visible above\",\"visible text\":[\"ようこそ NEONVEILへ！スマホチケットをご準備ください♪\",\"STEP 1 チケットを開く\",\"STEP 2 QRをかざす\",\"こんにちは！ボク、ネオン君だよ♪\"]},{\"number\":3,\"position\":\"middle-left\",\"scene\":\"mascot floats close to camera, gesturing proudly with one arm toward the venue entrance behind it, surrounded by dense sparkles\",\"visible text\":[\"NEONVEILの入り口で、みんなをご案内してるの!\"]},{\"number\":4,\"position\":\"middle-right\",\"scene\":\"mascot hovers beside a large transparent blue instructional UI showing the three-step smartphone ticket process, pointing upward as if explaining; visitors walk in the background through the atrium\",\"visible text\":[\"スマホチケットの準備も、ボクにおまかせ!\",\"STEP 1 チケットを開く\",\"STEP 2 QRをかざす\",\"STEP 3 入場完了!\"]},{\"number\":5,\"position\":\"bottom-left\",\"scene\":\"the young woman visitor in profile on the left clasps her hands shyly while the glowing mascot floats beside her, offering help in a comforting tone\",\"visible text\":[\"おひとりですか？ボクがお手伝いします♪\"]},{\"number\":6,\"position\":\"bottom-right\",\"scene\":\"final welcoming shot from behind the young woman and visitor group facing the NEONVEIL entrance; mascot floats on the right, winking with one big cyan eye, smiling, raising a paw, with a small pink heart and sparkles\",\"visible text\":[\"NEONVEIL\",\"さぁ、一緒に行こう！ようこそ、NEONVEILへ♪\"]}]},\"composition notes\":\"keep all six panels clearly separated with thin black borders, maintain consistent venue continuity across panels, use rounded white speech bubbles with soft blue outlines, make Japanese text crisp and legible, preserve a wholesome event-guide atmosphere\",\"customization\":{\"main dialogue theme\":\"{argument name=\\\"event welcome theme\\\" default=\\\"a cute mascot guiding visitors through smartphone ticket admission at NEONVEIL\\\"}\",\"final speech\":\"{argument name=\\\"final speech text\\\" default=\\\"さぁ、一緒に行こう！ようこそ、NEONVEILへ♪\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/17966.jpg"]},{"i":10022,"text":"{\"type\":\"technical blueprint character design sheet\",\"style\":\"dark navy engineering blueprint with fine cyan grid, thin white and pale blue line art, precise drafting annotations, dimension arrows, boxed tables, clean sci-fi UI typography, high-detail mechanical cutaway linework\",\"subject\":{\"name\":\"{argument name=\\\"android model name\\\" default=\\\"EVE-07\\\"}\",\"role\":\"{argument name=\\\"role subtitle\\\" default=\\\"SPACE MOBILITY VEHICLE PILOT\\\"}\",\"description\":\"female humanoid android, adult proportions, athletic curvy body, long flowing hair, robotic internal joints and armor segments visible as transparent schematic outlines, high-heel mechanical feet, blank dark rectangular face censor panel covering the face in each orthographic view\",\"materials\":\"ceramic composite armor, silicone synthetic muscle, titanium alloy frame, high-voltage caution components\"},\"canvas\":{\"orientation\":\"vertical poster\",\"background\":\"deep blue blueprint paper with subtle square grid and outer drafting border\",\"composition\":\"orthographic robot blueprint with three main body views on the left and center, data panels stacked on the right, notes and revision table at bottom right\"},\"header\":{\"position\":\"top left\",\"large title\":\"{argument name=\\\"android model name\\\" default=\\\"EVE-07\\\"}\",\"subtitle\":\"{argument name=\\\"role subtitle\\\" default=\\\"SPACE MOBILITY VEHICLE PILOT\\\"}\",\"small line\":\"Android / Female / Type-07\"},\"layout\":{\"main views\":{\"count\":3,\"views\":[{\"label\":\"FRONT VIEW\",\"position\":\"upper left\",\"description\":\"full-body front orthographic view, arms relaxed at sides, long hair around shoulders, detailed transparent torso, chest, hip, thigh, knee, ankle and foot mechanisms\",\"dimension labels\":[\"height 1670\",\"width 380\",\"shoulder-to-hip segmented measurements 250, 320, 450, 650\",\"foot width 220\"],\"callouts count\":12,\"callouts\":[\"OPTICAL SENSOR CAMERA UNIT\",\"NECK ACTUATOR VER. 07\",\"SHOULDER UNIT ROTATION 180°\",\"CHEST UNIT CERAMIC COMPOSITE ARMOR\",\"UPPER ARM UNIT SILICONE SYNTHETIC MUSCLE\",\"POWER CORE & CONTROL UNIT\",\"HIP UNIT FLEXIBLE MOVEMENT STRUCTURE\",\"HAND UNIT TACTILE SENSOR\",\"THIGH UNIT SILICONE SYNTHETIC MUSCLE\",\"KNEE ACTUATOR VER. 07\",\"LOWER LEG UNIT BALANCE CONTROL\",\"ANKLE ACTUATOR VER. 07\",\"FOOT UNIT MAGNETIC HEEL\"]},{\"label\":\"SIDE VIEW\",\"position\":\"upper center-right\",\"description\":\"full-body side orthographic view facing left, long hair falling down back, visible ear detail, bust and hip profile, arm hanging straight, mechanical leg and high heel foot\",\"dimension labels\":[\"height 1670\",\"head depth 210\",\"foot depth 240\"]},{\"label\":\"TOP VIEW\",\"position\":\"bottom left\",\"description\":\"top-down orthographic view of the android lying horizontally with arms slightly out, long hair radiating from crown, shoulders, torso, hips and legs visible as a dense mechanical outline\",\"dimension labels\":[\"width 380\",\"depth 210\"]}]},\"right side panels\":{\"count\":6,\"panels\":[{\"title\":\"SPECIFICATIONS\",\"position\":\"upper right\",\"rows count\":15,\"rows\":[\"MODEL: EVE-07\",\"TYPE: SPACE MOBILITY VEHICLE PILOT\",\"CLASS: α (ALPHA)\",\"HEIGHT: 1670 mm\",\"WEIGHT: 52 kg\",\"POWER OUTPUT: 120 %\",\"MAX OUTPUT: 120 %\",\"OPERATING TIME: 72 hr\",\"MATERIAL: CERAMIC COMPOSITE, SILICONE SYNTHETIC, TITANIUM ALLOY\",\"CPU: QUANTUM CORE α\",\"SENSOR: MULTI SPECTRUM, LIDAR / RADAR, TACTILE SENSOR\",\"MOBILITY: BIPEDAL\",\"ENVIRONMENT: SPACE\",\"TEMPERATURE: -20°C ~ +60°C\",\"PROTECTION: IP68\"]},{\"title\":\"MATERIAL LEGEND\",\"position\":\"right middle\",\"items count\":4,\"items\":[\"CERAMIC COMPOSITE\",\"SILICONE SYNTHETIC\",\"TITANIUM ALLOY\",\"CAUTION (HIGH VOLTAGE)\"]},{\"title\":\"JOINT RANGE\",\"position\":\"right middle-lower\",\"items count\":7,\"items\":[\"NECK ±90°\",\"SHOULDER 180°\",\"ELBOW 150°\",\"WRIST 180°\",\"HIP 120°\",\"KNEE 150°\",\"ANKLE 120°\"]},{\"title\":\"ID CHIP\",\"position\":\"lower right above notes\",\"description\":\"small technical ID plate with corner screws, barcode, tiny QR code and large text EVE-07\",\"id text\":\"ID:07-0217-α\"},{\"title\":\"NOTES\",\"position\":\"bottom right\",\"items count\":4,\"items\":[\"Four short Japanese-style technical note lines in small white text\", \"The notes appear as compact bullet points inside a rectangular box\", \"Use dense blueprint typography and do not make them the visual focus\", \"Keep them legible-looking but tiny\"]},{\"title\":\"REVISION\",\"position\":\"bottom right edge\",\"rows count\":2,\"columns\":[\"REV.\",\"DATE\",\"DESCRIPTION\",\"APPROVED\"],\"rows\":[\"1.0 | {argument name=\\\"revision date\\\" default=\\\"2024-05-07\\\"} | INITIAL RELEASE | {argument name=\\\"company name\\\" default=\\\"EVE CORP.\\\"}\"]}]},\"rendering requirements\":\"ultra clean vector-like blueprint line drawing, extremely detailed android anatomy and mechanical components, accurate orthographic alignment, fine measurement ticks and arrowheads, thin rectangular panel borders, no photorealistic lighting, no color except navy background and white/cyan drafting lines, no extra characters, no scenery\"}","imgs":["https://r2.qqsrc.com/images/originals/17968.jpg"]},{"i":10023,"text":"Create a cinematic neo-noir film still in a dark, intimate lounge with deep crimson walls and a plush red velvet sofa dominating the foreground. On the right, show {argument name=\"female subject\" default=\"a blonde woman in a pale champagne silk slip dress\"} seated on the sofa, leaning forward with one arm across her lap and holding a lit cigarette delicately in her raised hand; her face is intentionally obscured by a flat dark-brown rectangular privacy block. On the left, near a closed wooden door, place {argument name=\"male subject\" default=\"a man in a dark suit and tie\"} standing in profile with hands in his pockets, mostly in shadow, his face also obscured by a dark privacy block. The room should feel tense and secretive, with warm low-key lighting from a small table lamp behind the sofa casting amber light onto the red wall. Include two framed artworks on the wall, a dark statue or decorative object in the back right, heavy shadows, rich red and brown tones, soft film grain, shallow depth of field, and a widescreen 16:9 composition. Make it look like a moody 1970s psychological thriller scene, elegant but unsettling, with realistic photography, dramatic contrast, and no visible text.","imgs":["https://r2.qqsrc.com/images/originals/17969.jpg"]},{"i":10024,"text":"Create a wide 16:9 photorealistic game-engine skybox test scene viewed from a low first-person camera on a vast flat, nearly black asphalt or matte platform under a huge open blue sky. The composition is dominated by the sky: bright midday sun glowing slightly left of center near the horizon line, strong lens bloom, pale blue atmospheric gradient, and scattered thin wispy white cirrus clouds across the upper left and upper right. The ground is a dark featureless plane with subtle reflections and faint grid-like seams, stretching to a straight distant horizon. On the right side, place two simple modern industrial cuboid buildings: one large dark gray corrugated metal box building tilted in perspective with small narrow black rectangular windows, a dark doorway, and a few roof vents; farther right, a white rectangular building partially cropped by the frame with sparse vertical black windows. Add a thin glowing pink-red line or laser strip running from the bottom center foreground toward the horizon beside the buildings, creating a strong perspective guide. Include a few tiny floating dark oval objects near the horizon beneath the sun. Use Unreal Engine / Unity-style real-time rendering, crisp shadows, high dynamic range lighting, realistic skybox atmosphere, minimal urban test environment, no people, no text, no vehicles, clean cinematic screenshot aesthetic. The customizable scene should use {argument name=\"sky condition\" default=\"bright midday blue sky with wispy cirrus clouds\"}, {argument name=\"ground material\" default=\"nearly black asphalt platform\"}, {argument name=\"building style\" default=\"minimal corrugated industrial cuboid buildings\"}, {argument name=\"accent line color\" default=\"glowing pink-red\"}, and {argument name=\"camera perspective\" default=\"low first-person wide-angle view\"}.","imgs":["https://r2.qqsrc.com/images/originals/17970.jpg"]},{"i":10025,"text":"{\"type\":\"information-dense illustrated travel poster and route diary in ukiyo-e inspired anime style\",\"overall_style\":\"Edo-period Tokaido travelogue mixed with modern character sheet layout, hand-drawn ink lines, muted washi-paper colors, aged parchment background, woodblock print textures, taped photo cards, handwritten annotations, red seal stamps, playful but detailed GPT-image-2 composition\",\"main_subject\":{\"name\":\"{argument name=\\\"character name\\\" default=\\\"ゆんさん\\\"}\",\"appearance\":\"young anime traveler with short dusty pink hair, face intentionally left as a soft beige blur/blank mask, calm adventurous posture\",\"clothing\":\"dark indigo-gray kimono robe layered over black leggings, sash belt, tan hiking boots, large woven backpack with rolled travel gear, holding a wooden walking staff\",\"pose\":\"full-body standing on a coastal road at left, three-quarter view, walking-stick in one hand, backpack straps over shoulders\"},\"setting\":{\"theme\":\"{argument name=\\\"journey theme\\\" default=\\\"東海道五拾三次\\\"}\",\"background\":\"old Tokaido road beside the sea with pine branches overhead, travelers in the distance, blue water, village street, and Mount Fuji visible, all rendered like a Japanese woodblock print\",\"date_text\":\"{argument name=\\\"date text\\\" default=\\\"1833.5.3-5.5\\\"}\"},\"layout\":{\"canvas\":\"vertical poster, dense scrapbook/reference-sheet composition on cream parchment\",\"left_side\":{\"count\":1,\"description\":\"one large full-body character portrait occupying the left half\",\"vertical_title_label\":\"東海道五拾三次\"},\"top_photo_cards\":{\"count\":3,\"position\":\"upper center and upper right\",\"style\":\"Polaroid-like travel snapshots taped at the top with beige masking tape\",\"labels\":[\"日本橋（出発）\",\"箱根の山道\",\"由比の宿\"],\"contents\":[\"traveler in crowded Nihonbashi street\",\"traveler on Hakone mountain road\",\"traveler by coastal inn and sea\"]},\"center_note\":{\"count\":1,\"title\":\"〜ゆんゆん。。の旅メモ〜\",\"description\":\"handwritten travel diary card with Japanese notes, ending with a small red square stamp reading ゆん\"},\"checklist_panel\":{\"count\":13,\"title\":\"道中プラン（ゆんさん流）\",\"position\":\"middle right\",\"items\":[\"日本橋（出発！）\",\"品川宿（お急ぎョー！）\",\"川崎宿（名物・奈良茶飯）\",\"神奈川宿（にぎやか〜）\",\"戸塚宿（はじめての宿場めし）\",\"藤沢宿（江の島チラ見！）\",\"平塚宿（名物・干物ゲット）\",\"小田原宿（城下町ステキ）\",\"箱根宿（山道きついよ〜）\",\"三島宿（うなぎ！最高♪）\",\"沼津宿（深海魚こわ…）\",\"原宿（桜えびゲット！）\",\"吉原宿（富士山きれーい！）\"],\"extra_note\":\"つぎは 奥津宿へ！ with a tiny doodle character\"},\"map_panel\":{\"count\":1,\"title\":\"東海道五拾三次マップ\",\"position\":\"right side\",\"description\":\"hand-drawn map of the Tokaido route along the coast with mountains, Mount Fuji, sea, compass rose, and red numbered route dots\",\"numbered_stops_count\":13,\"numbered_stops\":[\"日本橋\",\"品川宿\",\"川崎宿\",\"神奈川宿\",\"戸塚宿\",\"藤沢宿\",\"平塚宿\",\"小田原宿\",\"箱根宿\",\"三島宿\",\"沼津宿\",\"原宿\",\"吉原宿\"]},\"bottom_thumbnail_strip\":{\"count\":13,\"position\":\"two rows across the lower half\",\"style\":\"small bordered ukiyo-e scene cards, each with a red circled number in the corner and a miniature traveler pose or landmark\",\"labels\":[\"① 日本橋（出発！）\",\"② 品川宿（急げョー！）\",\"③ 川崎宿（奈良茶飯で〜）\",\"④ 神奈川宿（にぎやか〜）\",\"⑤ 戸塚宿（はじめての宿場めし）\",\"⑥ 藤沢宿（江の島チラ見！）\",\"⑦ 平塚宿（干物最高！）\",\"⑧ 小田原宿（城かっこい！）\",\"⑨ 箱根宿（山道つら…）\",\"⑩ 三島宿（うなぎ最高！）\",\"⑪ 沼津宿（深海魚こわ…）\",\"⑫ 原宿（桜えびゲット！）\",\"⑬ 吉原宿（富士山きれーい！）\"],\"pose_descriptions\":[\"raising fist at departure\",\"eating while walking in town\",\"standing by harbor and bridge\",\"holding food in busy street\",\"snacking near shops\",\"shading eyes by the coast\",\"small proud gesture near sea\",\"posing before castle\",\"bent over tired on mountain road\",\"holding a bowl of eel rice\",\"eating by colorful market shelves\",\"holding shrimp snack\",\"side profile looking at Mount Fuji\"]},\"bottom_title\":{\"count\":1,\"text\":\"{argument name=\\\"large brush title\\\" default=\\\"ゆんさん五拾三次\\\"}\",\"style\":\"large bold black Japanese brush calligraphy across the bottom\"},\"stamps_and_marks\":{\"count\":2,\"descriptions\":[\"red square seal stamp at lower left beside the title\",\"tiny doodle signature and small sketch at lower right\"]}},\"rendering_instructions\":\"Make every panel legible and deliberately arranged like a travel-planning infographic. Preserve the Japanese labels exactly as written. Use soft beige face-blur masks on the character in every appearance. Balance historic Tokaido woodblock scenery with modern anime character design, detailed linework, faded ink, blue-green mountains, tan parchment, and red numbering accents.\"}","imgs":["https://r2.qqsrc.com/images/originals/17971.jpg"]},{"i":10026,"text":"Create a cute stylized 3D clay-rendered character on a clean white background: {argument name=\"character name\" default=\"Baba Yaga\"} as a squat elderly folklore witch wearing a large soft {argument name=\"hat color\" default=\"burnt orange-red\"} hood or cap, long gray hair hanging down on both sides, and a simple brown robe with rounded toy-like folds. Her face is deliberately hidden by one flat opaque square censor block in a warm brown skin tone, centered over the head and covering all facial features. She holds exactly one crooked wooden walking staff in her left hand. Beside and partly attached to her right side is exactly one miniature log cabin hut, made from rounded golden-brown logs, with exactly one arched wooden door, exactly one small square upper window, exactly one dark blue-gray shingled roof, and exactly one squat chimney. The hut stands on exactly two birdlike chicken legs with three front claws visible on each foot, sculpted in the same warm wood-clay style. Use soft studio lighting, smooth rounded forms, tactile polymer-clay texture, subtle ambient shadows, high detail, centered composition, isometric front three-quarter view, whimsical fairy-tale toy aesthetic, no text, no border.","imgs":["https://r2.qqsrc.com/images/originals/17972.jpg"]},{"i":10027,"text":"Create a polished 3D stylized fantasy mascot on a pure white background: a cute chibi witch-owl creature sitting inside a carved wooden bucket or half-barrel, rendered like a collectible game figurine with soft studio lighting, rounded shapes, warm colors, high detail, ambient occlusion, and a clean isolated product-shot composition. The character has a squat round body covered in dark brown feathers, orange bird feet with 6 visible talons total, shaggy pale cream hair, a muted purple headscarf tied in a bow on the right side, pointed orange ears, and a strange square faceless area over the front of the head in a smooth brown gradient. The creature holds 1 straw broom upright in its right hand and has 1 small glowing lantern hanging from the front of the barrel. On the left side are 2 props: 1 black cauldron filled with bright green bubbling potion with white steam, and 1 black crow perched beside it. On the ground to the right are 3 props: 1 cream skull, 1 red mushroom cap with white spots and green stem, and 1 small wooden base/stone patch. Use a whimsical Halloween cottagecore fantasy style, miniature diorama proportions, glossy eyes on the crow, carved wood grain on the bucket, orange lantern glow, saturated but cozy palette, no text, no border, centered composition. Customize the character as {argument name=\"character type\" default=\"chibi witch-owl creature\"}, the headscarf as {argument name=\"headscarf color\" default=\"muted purple\"}, the potion as {argument name=\"potion color\" default=\"bright green\"}, the accessory animal as {argument name=\"animal companion\" default=\"black crow\"}, and the held prop as {argument name=\"held prop\" default=\"straw broom\"}.","imgs":["https://r2.qqsrc.com/images/originals/17973.jpg"]},{"i":10028,"text":"Create a high-quality stylized 3D game asset of {argument name=\"subject\" default=\"a Baba Yaga chicken-leg hut\"}, centered on a transparent checkerboard background. The hut is an isometric three-quarter view facing slightly left, built from warm brown rounded log walls with visible circular log ends, a small arched wooden door on the front-right with a metal ring handle, and a small front window glowing orange from inside with open plank shutters. Add a short wooden ladder with three steps leading to the entrance. The roof is steep and whimsical, made of dark weathered wooden planks with green moss patches, curved golden-brown carved trim, an ornate peaked gable, and a chunky stone chimney near the back-right. The house stands on exactly two large bird-like legs with tan scaly texture, each ending in three forward toes and one rear toe with dark claws. Include small hanging charms on the right wall, including beads, bones, and a tiny skull. Use a polished fantasy miniature style, rounded shapes, hand-painted textures, soft ambient occlusion, subtle shadows, warm lighting, crisp edges, and no text.","imgs":["https://r2.qqsrc.com/images/originals/17974.jpg"]},{"i":10029,"text":"Create a single front-facing Chinese Taoist talisman on an off-white background, centered as a tall vertical rectangle of aged golden-yellow rice paper with subtle fibrous texture, slight mottling, and a thin red outer border plus inner red frame. Use deep cinnabar-red ink for the sacred graphics and mostly black ink for side calligraphy, with a hand-brushed, slightly imperfect printed look. The talisman contains 4 vertical text columns: left black column reading {argument name=\"left invocation text\" default=\"使天下所有 SOTA 大型模型 成本降為十分之一\"}, right black column reading {argument name=\"right invocation text\" default=\"敕令天曹地府 削減算力消耗 降成本費用\"}, a small red boxed column at lower left reading \"立降十成\", and a small red boxed column at lower right reading \"成本大降\". In the center, draw a large ornate red Taoist spell glyph with stacked Chinese characters, including a top title {argument name=\"central title text\" default=\"敕令靈畫\"} and the phrase {argument name=\"central reduction text\" default=\"十分之一\"}, shaped like a flowing ritual sigil with angular strokes. Above it place 1 yin-yang symbol inside a red circle, surrounded by 8 red bagua trigrams arranged symmetrically. Add 2 mirrored vertical red circuit-like ritual lines flanking the central glyph, each with circular nodes, giving a mystical-computing hybrid feeling. At the bottom center add 1 red square seal stamp containing four stylized characters, default text {argument name=\"seal text\" default=\"敕妙降本符\"}, and beneath it 1 small trigram mark. Decorate the four corners with 4 red flame-cloud ornaments and add fine red ornamental curls near the bottom corners. The composition should resemble an authentic Daoist paper charm redesigned as a humorous magical cost-reduction talisman for SOTA AI models, cleanly photographed or scanned, flat 2D, high resolution, no perspective distortion.","imgs":["https://r2.qqsrc.com/images/originals/17975.jpg"]},{"i":10030,"text":"{\"type\":\"side-by-side comparison graphic showing the importance of manga art style\",\"canvas\":\"16:9 horizontal composition with a solid vivid red background\",\"main_elements\":{\"count\":3,\"items\":[\"left manga page in generic polished anime style\",\"large yellow arrow pointing from left to right in the center\",\"right manga page in a distinctive simple gag-manga style\"]},\"left_page\":{\"position\":\"left third of canvas\",\"panel_count\":7,\"style\":\"modern clean school manga, soft shading, semi-realistic anime proportions, detailed classroom backgrounds, beige and brown palette, thin panel gutters, speech bubbles filled with Japanese text, classmates in navy uniforms, teacher at chalkboard, multiple student faces intentionally blurred with mosaic/soft blur to anonymize them\",\"subject\":\"a transfer student girl in a tan cardigan, white shirt, red bow, navy skirt, medium brown bob hair, standing and introducing herself in class, then sitting at a desk among classmates\",\"visible_sound_effects_count\":9,\"visible_sound_effects\":[\"ドキ\",\"ドキ\",\"パチパチ\",\"パチパチ\",\"ガヤガヤ\",\"ニコニコ\",\"スタスタ\",\"スタスタ\",\"パチパチパチ\"],\"overall_impression\":\"competent but generic, no distinctive visual identity\"},\"right_page\":{\"position\":\"right third of canvas\",\"panel_count\":5,\"style\":\"highly distinctive retro children’s gag manga, thick uneven black outlines, flat saturated colors, intentionally simple faces, exaggerated expressions, hand-drawn panel borders, bold katakana sound effects, energetic composition, looks like a unique personal comic style rather than generic anime\",\"subject\":\"a black-haired elementary school transfer girl wearing a blue shirt with the number 2 introduces herself to a classroom; classmates react enthusiastically and clap\",\"character_design\":\"round face, straight black hair with blunt bangs, dot eyes or simple oval eyes, wide open pink mouth, tiny simplified body, very thick ink lines\",\"color_palette\":\"hot pink, cyan blue, yellow, green, white, black, high contrast\",\"visible_sound_effects_count\":6,\"visible_sound_effects\":[\"ドキドキ\",\"おおー\",\"じゃんっ\",\"ペコリ\",\"パチ パチ パチ\",\"よろしく!\"],\"speech_bubble_text_count\":7,\"speech_bubble_text\":[\"みなさん はじめまして!\",\"今日からこのクラスに転校してきました\",\"わたしの名前はさくらです!\",\"えがおで楽しくがんばるのでよろしくお願いします!\",\"ありがとうございます!\",\"よろしく!\",\"今日から転校してきました!\"]},\"center_arrow\":{\"position\":\"center between pages\",\"color\":\"bright yellow\",\"shape\":\"large thick right-pointing arrow\",\"meaning\":\"transformation from no art-style specification to a specified distinctive style\"},\"composition_notes\":\"Both manga pages are shown as complete rectangular pages with white margins and black gutters, slightly separated on the red background. The left page should look like an ordinary AI manga output; the right page should clearly feel more memorable, stylized, and original. Do not include extra captions outside the manga pages and arrow.\",\"customizable_text\":{\"comparison theme\":\"{argument name=\\\"comparison theme\\\" default=\\\"AI manga is 90% art style\\\"}\",\"left style\":\"{argument name=\\\"left style\\\" default=\\\"generic polished anime school manga\\\"}\",\"right style\":\"{argument name=\\\"right style\\\" default=\\\"distinctive retro children’s gag manga\\\"}\",\"transfer student name\":\"{argument name=\\\"transfer student name\\\" default=\\\"さくら\\\"}\",\"background color\":\"{argument name=\\\"background color\\\" default=\\\"vivid red\\\"}\"}}","imgs":["https://r2.qqsrc.com/images/originals/17977.jpg"]},{"i":10031,"text":"Create a simple low-resolution pixel art illustration on a plain white background, centered on a chibi-style ninja or masked warrior with messy black spiky hair, round black eyes, pale skin, and a black face covering. The character wears a dark green robe or cloak and carries a katana diagonally across the back, with a green handle and white guard visible over the right shoulder. Above the character floats a chunky yellow pixel crown with black outline and tiny white shine marks, tilted slightly. To the upper right, add a hand-drawn comic speech bubble outlined in black containing the text {argument name=\"speech bubble text\" default=\"When 2026?\"} in uneven handwritten black lettering. Use a deliberately rough, viral meme-like aesthetic with thick black pixel outlines, jagged edges, scattered tiny black specks, minimal shading, and a cropped square composition where the lower body is cut off at the bottom. The character should feel cute but mysterious, like a crowned pixel ninja asking a question.","imgs":["https://r2.qqsrc.com/images/originals/17978.jpg"]},{"i":10032,"text":"Create a realistic vertical portrait photograph of a {argument name=\"subject\" default=\"Japanese high school girl\"} standing in a warm sunlit classroom after school, wearing a traditional navy sailor-style school uniform with white striped collar and cuffs, a bright red neckerchief, and a dark pleated skirt. She has long dark hair styled into two neat braids falling over her shoulders, stands slightly angled with her hands held behind her back, and her face is fully covered by a plain rectangular censor block in a natural skin-tone brown. The classroom has wooden desks and chairs around her, notebooks on the desks, a polished wooden floor, cream curtains, and golden late-afternoon sunlight streaming through tall windows on the left. Behind her is a green chalkboard with handwritten Japanese chalk text reading {argument name=\"chalkboard quote\" default=\"青春とは、心の若さである。 by サミュエル・ウルマン\"}. Use photorealistic detail, soft cinematic lighting, shallow depth of field, nostalgic Japanese school atmosphere, warm color grading, 3:4 vertical composition, subject centered from mid-thigh upward, SFW.","imgs":["https://r2.qqsrc.com/images/originals/17979.jpg"]},{"i":10033,"text":"Using REFERENCE_0 as the food subject, transform the photo into a refined vintage scientific specimen plate / illustrated food diagram on a clean off-white paper background. Preserve the same sizzling-plate meal components and overall arrangement, but redraw them as detailed hand-colored botanical/culinary field-guide illustrations with ink outlines, watercolor texture, subtle paper grain, and precise diagram callouts. Add a centered Traditional Chinese title {argument name=\"main title\" default=\"鐵板標本圖鑑\"}, a subtitle {argument name=\"subtitle\" default=\"香煎雞腿排・荷包蛋・青花菜・蘑菇醬鐵板麵\"}, and small plate-number typography in the top corners. Create exactly 4 numbered annotation sections around the main dish: I. 香煎雞腿排, II. 青花菜, III. 蘑菇醬鐵板麵, IV. 荷包蛋, each with short Traditional Chinese explanatory text and dotted leader lines pointing to the corresponding ingredient. Add exactly 4 square letter markers on the dish and legend: A 香煎雞腿排, B 青花菜, C 荷包蛋, D 蘑菇醬鐵板麵. Include exactly 6 supplemental illustrations/insets: a close-up of the seared chicken surface, a broccoli specimen with approximate size marks, a noodle close-up, a fried egg close-up, a small skillet of mushroom cream sauce, and a low side-view cross-section of the entire plated meal. Add two small boxed notes near the bottom, one legend box and one observation note box, plus footer text including {argument name=\"observer\" default=\"美食愛好者\"}, {argument name=\"observation date\" default=\"2024 年\"}, and {argument name=\"location\" default=\"臺灣・日常餐桌\"}. Keep the composition poster-like, balanced, educational, appetizing, and more polished than the original photo.","imgs":["https://r2.qqsrc.com/images/originals/17980.jpg"]},{"i":10034,"text":"Create a deliberately crude MS Paint / low-resolution pixel doodle on a plain white background, centered composition. Draw a cartoon bust of a mysterious king-like ninja character with messy spiky {argument name=\"hair color\" default=\"black\"} hair, pale beige skin, narrow rectangular sleepy eyes with black outlines, and a face mostly covered by a thick black mask or beard shape. He wears a rough dark {argument name=\"cloak color\" default=\"green\"} cloak with jagged edges and white scratchy highlights. A large diagonal sword or katana handle crosses from the lower left of the body up to the right shoulder, with a dark green grip, black blade or strap, and small gray guard. Floating above his head is an oversized jagged {argument name=\"crown color\" default=\"yellow\"} crown with black outline and white base, tilted slightly left, drawn with scribbly yellow fill. To the upper right, add exactly 1 rounded speech bubble with a black outline and small tail pointing toward the character; inside it write the hand-drawn text {argument name=\"speech bubble text\" default=\"when 2026?\"}. Use thick uneven black pixelated outlines, rough hand-sketched strokes, minimal colors, intentionally messy proportions, childlike digital drawing style, no shading beyond scribbles, no background details.","imgs":["https://r2.qqsrc.com/images/originals/17981.jpg"]},{"i":10035,"text":"Create a cinematic ultra-realistic wide-angle photo of two giant humanoid painting robots facing off in an ornate, dimly lit museum gallery at night. On the left, a battered white chrome robot with peeling paint, exposed mechanical joints, splattered pigments, a glowing blue eye, and the multicolored {argument name=\"left robot logo\" default=\"Google\"} wordmark across its chest leans forward aggressively. On the right, a darker gunmetal chrome robot with glossy black mechanical limbs, paint stains, a bright white eye light, and a glowing {argument name=\"right robot logo\" default=\"OpenAI knot logo\"} emblem on its chest holds a wooden paintbrush like a sword in one hand and a colorful artist palette in the other. The robots should look enormous, scratched, dented, wet with reflective paint, and illuminated by dramatic warm museum lighting mixed with cold blue robot lights. Behind them, show a crowd of photographers and spectators behind a barrier, with one intense camera flash bursting in the center background; faces are slightly blurred for realism. The setting is a grand classical interior with tall columns, arched doorways, dark wood ceiling beams, gilded wall sconces, and deep shadows. Use strong perspective, low camera angle, 2.39:1 cinematic aspect ratio, shallow depth of field, high contrast, lens flare, gritty photorealism, blockbuster robot duel atmosphere, no captions or extra text beyond the chest logos.","imgs":["https://r2.qqsrc.com/images/originals/17982.jpg"]},{"i":10036,"text":"Create a monumental {argument name=\"painting style\" default=\"Baroque oil painting with Romantic-era grandeur\"} depicting a colossal {argument name=\"mechanical deity\" default=\"golden clockwork titan\"} emerging from stormy, radiant clouds above an ancient crowd. The titan is enormous and divine, built from intricate brass and gold gears, engraved armor plates, pistons, rings, clock faces, and celestial machinery; its head is a dense crown of rotating mechanical structures with a single blazing golden light at the center like an eye. Show the figure from a dramatic low angle, with one massive articulated hand reaching down toward the viewer in extreme foreshortening, fingers made of cylindrical metal segments and ornate joints. Behind its head, place a circular halo of glowing mechanical rings and sunburst light, sending warm rays through towering dark clouds. Below, depict a vast crowd of robed ancient people in awe, many raising their arms toward the titan; include ruined classical architecture and columns at the left and right edges for scale. Use a cinematic wide composition, chiaroscuro lighting, deep shadows, glowing amber highlights, smoky atmosphere, turbulent clouds, dense painterly brushwork, intricate detail, mythic apocalyptic mood, and museum-quality classical realism. Keep the palette dominated by {argument name=\"main color palette\" default=\"antique gold, bronze, umber, charcoal gray, and warm celestial amber\"}. No modern text, no sci-fi neon, no cartoon styling; make it feel like a lost grand master painting of a divine machine descending from heaven.","imgs":["https://r2.qqsrc.com/images/originals/17983.jpg"]},{"i":10037,"text":"A radiant young woman with dewy, glowing skin lies on a soft {argument name=\"towel style\" default=\"blue-and-white striped\"} towel under bright natural sunlight, holding a {argument name=\"color\" default=\"pastel blue\"} sunscreen tube labeled “LUMASKIN Sun Veil SPF Cream” gently against her cheek. She has a relaxed expression, minimal makeup, and slightly tousled dark hair styled in a loose bun. Surrounding her are fresh summer elements: bowls of blueberries and raspberries, sliced grapefruit on a plate, and a glass of pink fruit-infused drink with berries and ice. The composition is a top-down flat lay with vibrant colors, crisp shadows, and a fresh, summery skincare advertisement aesthetic, high detail, soft highlights, and a clean lifestyle beauty photography style.","imgs":["https://r2.qqsrc.com/images/originals/18024.jpg"]},{"i":10038,"text":"1. A vibrant fusion street-food scene where a sizzling plate of smoky fried rice biryani blends aromatic spices with golden grains, beside a rich, slow-cooked mutton dish glistening with gravy. Steaming hot momos sit in a bamboo basket, releasing curls of fragrant steam, while a chilled mint mojito sparkles with ice, fresh mint leaves, and lime slices. The setting is a lively night market under warm lights, with colors, textures, and aromas colliding into a bold, modern culinary fusion aesthetic. 2. An eye-catching food scene featuring a delicious spread of fast food and refreshing drinks: a juicy pizza with melted cheese, a stacked burger with crispy lettuce and sauce, a bowl of steaming noodles, golden crispy fries, a chilled mojito with mint and lime, and fresh slices of juicy watermelon. The setting is vibrant and colorful, with soft lighting, high detail, and a modern aesthetic, arranged beautifully on a wooden table, top-down view, ultra-realistic, 4K quality.","imgs":["https://r2.qqsrc.com/images/originals/18025.jpg"]},{"i":10039,"text":"Make a 3:4 format infographic about {argument name=\"topic\" default=\"camera lenses and apertures in cinema\"}.\n\nI want an area with classifications of lenses: {argument name=\"focal lengths\" default=\"14–24, 35–50mm, 85–135\"} (3 categories).\n\nAnd then another area with apertures: {argument name=\"aperture values\" default=\"1.4, 2.8–4, and 5.6–8\"} (3 categories).\n\nPut below each type of aperture an example to see the background blur, and below each type of lens an example to see the perspective.\n\nThey would be: 3 types of lenses, three types of focal lengths + golden standard in cinema (most common used setup).\n\nAnd at the very bottom, examples of the 4 most used configurations.","imgs":["https://r2.qqsrc.com/images/originals/18027.jpg"]}];